81	function titleCase(word: string) {
82	  if (word.length > 1 && word === word.toUpperCase()) return word;
83	  return word
84	    .split("-")
85	    .map((w) => (w ? w[0].toUpperCase() + w.slice(1).toLowerCase() : w))
