    Config.Defaults = {
        ${opts.map((o) => `${o[0].padEnd(width)} = ${val(o)}, -- ${o[5]}`)}
    }

    --- Reads a sandbox option, falling back to the shipped default.
    function Config.get(key)
        local vars = SandboxVars and SandboxVars[Config.MOD_ID]
        local value = vars and vars[key]
        if value == nil then value = Config.Defaults[key] end
        return value
    end

    function Config.clamp(value, lo, hi)
        return math.max(lo, math.min(hi, value))
    end

    --- Real-time cooldown gate; timestamps come from getTimestampMs().
    function Config.ready(lastMs, nowMs, seconds)
        return lastMs == nil or nowMs - lastMs >= seconds * 1000
    end

