    : "";
  const COMMANDS = has("world")
    ? code`
      local Commands = {}

      function Commands.worldFx(player, args)
          local apply = WorldFx[args.key]
          local square = apply and getCell():getGridSquare(args.x, args.y, args.z)
          if not square then return end
          -- never trust a client blindly: the square has to be near the sender
          if IsoUtils.DistanceTo(player:getX(), player:getY(), args.x, args.y) > 30 then return end
