    const lists = weapon ? ["GarageTools", "CrateTools", "ToolStoreTools"] : magic ? ["BedroomDresser", "BedroomSideTable", "CrateRandomJunk"] : ["CrateTools", "GarageTools", "CrateRandomJunk"];
    const server = file(`${L}/server/${cls}Server.lua`, code`
