    /* ═════════ entity: creatures ═════════ */
  } else if (k === "creatures") {
    const client = file(`${L}/client/${cls}Zombies.lua`, code`
      ${clientHead("zombie behaviour")}
      local OUTFIT = "${lead.outfit}"

      ${STATE}

      ${REQUEST}

      ${fxDefs(["foe", "self"])}

      --- Rolled from the persistent outfit ID, so a variant stays a variant across reloads and clients.
      local function isVariant(zombie)
          local st = state(zombie)
          if st.variant == nil then
              st.variant = zombie:getOutfitName() == OUTFIT and Config.isVariant(zombie:getPersistentOutfitID(), Config.get("SpawnChance"))
          end
          return st.variant
      end

