          st.awake = true
          zombie:setWalkType(Config.walkType(Config.get("WalkType"), zombie:getPersistentOutfitID()))
          zombie:setHealth(Config.get("Health"))
      end

      --- OnZombieUpdate runs every tick for every loaded zombie: bail out early and cheaply.
      local function onZombieUpdate(zombie)
          if not isVariant(zombie) then return end
          local st = state(zombie)
          if not st.awake then awaken(zombie, st) end

          local target = zombie:getTarget()
          if not target or not instanceof(target, "IsoPlayer") or not target:isLocalPlayer() then return end
          if zombie:DistTo(target) > Config.get("Radius") then return end

          local now = getTimestampMs()
