          st.lastAbility = now

          local power = Config.get("Power")
          ${calls(["foe", "self", "world"], "target", "zombie", (key) => `requestWorldFx(target, "${key}", zombie:getX(), zombie:getY(), zombie:getZ())`)}
          -- the shriek: everything in earshot turns toward the fight
          getWorldSoundManager():addSound(zombie, math.floor(zombie:getX()), math.floor(zombie:getY()), math.floor(zombie:getZ()), math.floor(power * 3), 50)
      end

      Events.OnZombieUpdate.Add(onZombieUpdate)`);
    const server = file(`${L}/server/${cls}Server.lua`, code`
      ${serverHead("server")}
      local OUTFIT = "${lead.outfit}"
      local DROP = "${lead.drop}"

      ${PLAYERS}

      ${RING}

      ${fxDefs(["world"])}

