      local LAYERS = { Calm = "${cls}_Calm", Tension = "${cls}_Tension", Combat = "${cls}_Combat" }
      local current = { layer = nil, audio = nil, gain = 0 }
      local fading = {}

      local function zombiesNear(player, radius)
