      end

      --- Picks the layer once per in-game minute; the crossfade itself happens in OnTick.
      local function evaluate()
          local player = getSpecificPlayer(0)
          if not player or player:isDead() or not Config.get("Enabled") then return end
          local hour = getGameTime():getHour()
          local zombies = zombiesNear(player, Config.get("ThreatRadius"))
          local layer = Config.layerFor(zombies, hour >= 21 or hour < 5, Config.get("CombatThreshold"))
          if layer == current.layer then return end
          if current.audio then table.insert(fading, { audio = current.audio, gain = current.gain }) end
          current.layer, current.gain = layer, 0
          current.audio = getSoundManager():PlaySound(LAYERS[layer], true, 0.0)
          if layer == "Combat" then getSoundManager():playUISound("${cls}_Stinger") end
      end

      local function onTick()
          local step = Config.get("FadeSpeed") * getGameTime():getRealworldSecondsSinceLastUpdate()
          if current.audio then
              current.gain = Config.approach(current.gain, Config.get("Volume") * getCore():getOptionMusicVolume() / 10, step)
              current.audio:setVolume(current.gain)
          end
          for i = #fading, 1, -1 do
              local f = fading[i]
              f.gain = Config.approach(f.gain, 0, step)
              f.audio:setVolume(f.gain)
              if f.gain <= 0 then
                  f.audio:stop()
                  table.remove(fading, i)
              end
          end
      end

      Events.EveryOneMinute.Add(evaluate)
      Events.OnTick.Add(onTick)
      Events.OnPlayerDeath.Add(function()
          if current.audio then current.audio:stop() end
          current.layer, current.audio = nil, nil
