          assert.is_true(Config.inZone(z.x + z.w / 2, z.y + z.h / 2))
          assert.is_false(Config.inZone(0, 0))
      end)`,
    mechanics: code`
      it("fires on every ${interval}${interval === 1 ? "st" : interval === 2 ? "nd" : interval === 3 ? "rd" : "th"} night and grows", function()
          assert.is_false(Config.isEventNight(0, ${interval}))
          assert.is_true(Config.isEventNight(${interval * 2}, ${interval}))
          assert.are.equal(20, Config.hordeSize(20, ${interval}, ${interval}, 400))
          assert.are.equal(25, Config.hordeSize(20, ${interval * 2}, ${interval}, 400))
          assert.are.equal(22, Config.hordeSize(20, ${interval * 9}, ${interval}, 22))
      end)`,
    quests: code`
      it("advances only when the goal is met", function()
          assert.are.equal(1, Config.advance(1, 0))
          assert.are.equal(2, Config.advance(1, 1))
          assert.are.equal(Config.Defaults.KillGoal, Config.goal(Config.Stages[2]))
      end)`,
    interface: code`
      it("maps zombie counts to threat levels", function()
          assert.are.equal(0, Config.threat(0, 4))
          assert.are.equal(1, Config.threat(3, 4))
          assert.are.equal(3, Config.threat(40, 4))
      end)`,
    audio: code`
      it("picks layers and fades smoothly", function()
          assert.are.equal("Calm", Config.layerFor(0, false, 5))
          assert.are.equal("Tension", Config.layerFor(0, true, 5))
          assert.are.equal("Combat", Config.layerFor(5, false, 5))
          assert.are.equal(0.25, Config.approach(0, 1, 0.25))
      end)`,
    visual: code`
      it("eases in at night", function()
          assert.are.equal(1, Config.nightFactor(0))
          assert.are.equal(0, Config.nightFactor(12))
          assert.are.equal(5, Config.lerp(0, 10, 0.5))
      end)`,
  };
  const test = file(`tests/${snake}_spec.lua`, code`
    -- busted spec for ${input.modName} · run from the mod root: busted tests
    package.path = "42/media/lua/shared/?.lua;" .. package.path

    local Config = require("${cls}/Config")

    describe("${cls} Config", function()
        after_each(function() _G.SandboxVars = nil end)

        it("falls back to the shipped defaults", function()
            assert.are.equal(${val(probe)}, Config.get("${probe[0]}"))
        end)

        it("prefers SandboxVars.${cls}", function()
            _G.SandboxVars = { ${cls} = { ${probe[0]} = ${val(probe, probe[4])} } }
            assert.are.equal(${val(probe, probe[4])}, Config.get("${probe[0]}"))
        end)

        it("gates on real-time cooldowns", function()
            assert.is_true(Config.ready(nil, 0, 5))
            assert.is_false(Config.ready(1000, 5000, 5))
            assert.is_true(Config.ready(1000, 6000, 5))
        end)

        ${TESTS[arch === "entity" || arch === "system" ? (k === "creatures" || k === "characters" || k === "vehicles" || k === "mechanics" || k === "quests" || k === "interface" || k === "audio" ? k : "mechanics") : arch]}
    end)`);

  return { files, config, l10n, test };
}

