import type { CategoryKey, ModFile } from "@/lib/types";
import { ARCH, code, deriveFeatures, effectsFor, file, hashStr, identity, MODEL_NAME, numbers, type Built, type EffectKey, type TemplateInput } from "../kit";

/* ═════════════════════════ Project Zomboid · Lua · Build 42 ═════════════════════════ */

/**
 * Effects as PZ Lua. foe(target, source, power) hits a zombie or player, self(who, power) acts on the
 * user, world(square, source, power) touches the map and so only ever runs on the server.
 */
type Kind = "foe" | "self" | "world";
interface PzFx { kind: Kind; lua: string; hud: [string, string]; outfit: string; drop: string; part: string }

const FX: Record<EffectKey, PzFx> = {
  frost: { kind: "foe", outfit: "Hunter", drop: "Base.Matches", part: "Base.Aluminum", hud: ["Body temp", 'string.format("%.1f C", player:getBodyDamage():getTemperature())'], lua: `if instanceof(target, "IsoZombie") then
    target:setWalkType("slow3")
else
    local body = target:getBodyDamage()
    body:setTemperature(math.max(34.5, body:getTemperature() - power * 0.08))
    target:getStats():setFatigue(math.min(1.0, target:getStats():getFatigue() + 0.05))
end` },
  fire: { kind: "world", outfit: "Fireman", drop: "Base.Lighter", part: "Base.PropaneTank", hud: ["Outside", 'string.format("%.0f C", getClimateManager():getTemperature())'], lua: `if not square:Is(IsoFlagType.water) and not square:haveFire() then
    IsoFireManager.StartFire(getCell(), square, true, math.floor(60 + power * 4))
end` },
  storm: { kind: "world", outfit: "Police", drop: "Base.Battery", part: "Base.Battery", hud: ["Rain", 'string.format("%d%%", getClimateManager():getPrecipitationIntensity() * 100)'], lua: `getClimateManager():getThunderStorm():triggerThunderEvent(square:getX(), square:getY(), true, true, true)
getWorldSoundManager():addSound(source, square:getX(), square:getY(), square:getZ(), math.floor(power * 4), 100)` },
  blink: { kind: "self", outfit: "Survivalist", drop: "Base.ElectronicsScrap", part: "Base.ElectronicsScrap", hud: ["Endurance", 'string.format("%d%%", player:getStats():getEndurance() * 100)'], lua: `local dir = who:getForwardDirection()
local reach = math.min(8, 2 + power * 0.4)
local x, y = who:getX() + dir:getX() * reach, who:getY() + dir:getY() * reach
local square = getCell():getGridSquare(math.floor(x), math.floor(y), math.floor(who:getZ()))
if square and square:isFree(false) then
    who:setX(x)
    who:setY(y)
    who:setLx(x)
    who:setLy(y)
end` },
  heal: { kind: "self", outfit: "Doctor", drop: "Base.Bandage", part: "Base.Bandage", hud: ["Health", 'string.format("%d%%", player:getBodyDamage():getOverallBodyHealth())'], lua: `if instanceof(who, "IsoPlayer") then
    who:getBodyDamage():AddGeneralHealth(power * 0.5)
else
    who:setHealth(who:getHealth() + power * 0.01)
end` },
  poison: { kind: "foe", outfit: "HazardSuit", drop: "Base.Hat_GasMask", part: "Base.Bleach", hud: ["Poison", 'string.format("%d", player:getBodyDamage():getPoisonLevel())'], lua: `if instanceof(target, "IsoPlayer") then
    local body = target:getBodyDamage()
    body:setPoisonLevel(math.min(100, body:getPoisonLevel() + power * 2))
else
    target:setHealth(target:getHealth() - power * 0.02)
    if target:getHealth() <= 0 then target:Kill(source) end
end` },
  summon: { kind: "world", outfit: "Inmate", drop: "Base.Garbagebag", part: "Base.RippedSheets", hud: ["Kills", "tostring(player:getZombieKills())"], lua: `local pack = addZombiesInOutfit(square:getX(), square:getY(), square:getZ(), math.max(1, math.floor(power / 4)), nil, 50)
for i = 0, pack:size() - 1 do
    pack:get(i):pathToSound(math.floor(source:getX()), math.floor(source:getY()), math.floor(source:getZ()))
end` },
  flight: { kind: "self", outfit: "Biker", drop: "Base.Rope", part: "Base.Rope", hud: ["Gait", 'player:isSprinting() and "sprint" or player:isRunning() and "run" or "walk"'], lua: `if instanceof(who, "IsoPlayer") then
    local stats = who:getStats()
    stats:setEndurance(math.min(1.0, stats:getEndurance() + 0.2))
    who:setRunSpeedModifier(1.0 + power / 25)
else
    who:setWalkType("sprint" .. tostring(ZombRand(3) + 1))
end` },
  void: { kind: "foe", outfit: "Priest", drop: "Base.Candle", part: "Base.Candle", hud: ["Panic", 'string.format("%d%%", player:getStats():getPanic())'], lua: `if instanceof(target, "IsoPlayer") then
    local stats = target:getStats()
    stats:setPanic(math.min(100, stats:getPanic() + power * 3))
else
    target:setTarget(nil)
end` },
  lunar: { kind: "foe", outfit: "Nurse", drop: "Base.Torch", part: "Base.Candle", hud: ["Time", 'string.format("%02d:%02d", getGameTime():getHour(), getGameTime():getMinutes())'], lua: `local hour = getGameTime():getHour()
if hour >= 21 or hour < 5 then
    if instanceof(target, "IsoPlayer") then
        target:getStats():setFatigue(math.min(1.0, target:getStats():getFatigue() + 0.04))
    else
        target:setHealth(target:getHealth() - power * 0.03)
        if target:getHealth() <= 0 then target:Kill(source) end
    end
end` },
  auto: { kind: "self", outfit: "ConstructionWorker", drop: "Base.Screwdriver", part: "Base.Wire", hud: ["Queue", "tostring(#ISTimedActionQueue.getTimedActionQueue(player).queue)"], lua: `if not instanceof(who, "IsoPlayer") or not who:isLocalPlayer() or ISTimedActionQueue.isPlayerDoingAction(who) then return end
local bag = who:getClothingItem_Back()
if not bag or not instanceof(bag, "InventoryContainer") then return end
local inv, dest = who:getInventory(), bag:getItemContainer()
local items = inv:getItems()
for i = items:size() - 1, 0, -1 do
    local item = items:get(i)
    if item:getCategory() == "Food" and not item:isFavorite() and not who:isEquipped(item) and dest:hasRoomFor(who, item) then
        ISTimedActionQueue.add(ISInventoryTransferAction:new(who, item, inv, dest))
    end
end` },
  neon: { kind: "self", outfit: "Punk", drop: "Base.LightBulb", part: "Base.LightBulb", hud: ["Moodles", "tostring(player:getMoodles():getNumMoodles())"], lua: `if instanceof(who, "IsoPlayer") and who:isLocalPlayer() then
    who:setHaloNote(getTextOrNull("IGUI_$CLS_Proc") or "$NAME", $RGB, 250)
end` },
};

/** Item and NPC contexts summon decoys instead of hunters: useless "echoes" that pull the horde away. */
const ECHO = `local echoes = addZombiesInOutfit(square:getX(), square:getY(), square:getZ(), 2, "$OUTFIT", 50)
for i = 0, echoes:size() - 1 do
    local echo = echoes:get(i)
    echo:setUseless(true)
    getWorldSoundManager():addSound(echo, square:getX(), square:getY(), square:getZ(), math.floor(power * 3), 60)
end`;

const PLACES = [
  { name: "Muldraugh", x: 10630, y: 9560 },
  { name: "West Point", x: 11860, y: 6890 },
  { name: "Riverside", x: 6420, y: 5300 },
  { name: "Rosewood", x: 8080, y: 11650 },
  { name: "March Ridge", x: 10020, y: 12680 },
];

const ORDINAL: Record<string, number> = { other: 2, second: 2, third: 3, fourth: 4, fifth: 5, sixth: 6, seventh: 7, eighth: 8, ninth: 9, tenth: 10 };

type Opt = [key: string, type: "boolean" | "integer" | "double" | "enum", def: number | boolean, min: number, max: number, label: string, tip: string, values?: string[]];
const dbl = (v: number | boolean) => (typeof v === "number" && Number.isInteger(v) ? v.toFixed(1) : String(v));
const val = (o: Opt, v = o[2]) => (o[1] === "double" ? dbl(v) : String(v));

export function zomboidLua(input: TemplateInput): Built {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const k = input.category.key;
  const arch = ARCH[k];
  const lite = input.model === "katara";
  const name = input.modName.replace(/["\\]/g, "");
  const prompt = input.prompt.toLowerCase();
  const tint = fxs[0].tint.map((c) => Math.round(c * 255)).join(", ");
  const lead = FX[fxs[0].key];
  const has = (kind: Kind) => fxs.some((e) => FX[e.key].kind === kind);
  const L = "42/media/lua";
  const S = "42/media/scripts";
  const ord = prompt.match(/every\s+(\d+|[a-z]+?)(?:st|nd|rd|th)?\s+(?:night|day)/)?.[1];
  const interval = ord ? Number(ord) || ORDINAL[ord] || n.interval : n.interval;
  const horde = /horde|siren|alarm|wave|swarm|migrat|night/.test(prompt);
  const place = PLACES[hashStr(cls) % PLACES.length];

  const ui = new Map<string, string>([["Title", name]]);
  const T = (key: string, text: string) => (ui.set(key, text), `txt("${key}", "${text}")`);
  if (fxs.some((e) => e.key === "neon")) ui.set("Proc", name);

  /* ── sandbox options: one list drives sandbox-options.txt, Sandbox_EN and Config.Defaults ── */
  const ON: Opt = ["Enabled", "boolean", true, 0, 0, "Enabled", "Turns the mod on or off for this save."];
  const POWER: Opt = ["Power", "double", n.power, 0, 50, "Effect power", "Strength of every effect this mod applies."];
  const COOL = (label: string, def = n.cooldown): Opt => ["Cooldown", "double", def, 0, 120, label, "Real-time seconds before it can trigger again."];
  const RADIUS = (label: string, def = n.radius): Opt => ["Radius", "integer", def, 1, 30, label, "Measured in tiles."];
  const LOOT: Opt = ["LootWeight", "double", 1, 0, 10, "Loot weight", "Multiplier on how often it appears in containers."];
  const OPTS: Record<CategoryKey, Opt[]> = {
    weapons: [ON, ["Power", "double", n.power, 0, 50, "Bonus power", "Extra damage per hit and the strength of on-hit effects."], ["Chance", "double", n.chance, 0, 1, "Proc chance", "Chance that a hit triggers the special effect."], COOL("Proc cooldown (s)"), LOOT],
    items: [ON, POWER, RADIUS("Effect radius"), COOL("Recharge (s)"), LOOT],
    magic: [ON, POWER, RADIUS("Spell radius"), COOL("Recast (s)"), ["EnduranceCost", "double", n.chance, 0, 1, "Endurance cost", "Endurance drained per cast (1.0 = a full bar)."], LOOT],
    creatures: [ON, POWER, ["SpawnChance", "double", n.chance, 0, 1, "Pack chance", "Chance per night hour that a pack starts hunting each player."], ["PackSize", "integer", n.interval + 2, 1, 40, "Pack size", "Zombies per pack."], ["Health", "double", +(n.health / 300).toFixed(2), 0.1, 10, "Variant health", "1.0 is roughly a vanilla zombie."], ["WalkType", "enum", 3, 1, 3, "Variant speed", "How variants move once they wake up.", ["Shamblers", "Fast shamblers", "Sprinters"]], RADIUS("Ability range"), COOL("Ability cooldown (s)"), ["DropChance", "double", 0.25, 0, 1, "Drop chance", "Chance a variant carries something useful."]],
    characters: [ON, POWER, ["Price", "integer", Math.round(n.power), 1, 100, "Price (bills)", "Money a trade costs before discounts."], ["TradeCooldown", "integer", n.interval * 2, 0, 168, "Trade cooldown (hours)", "In-game hours between two trades."], RADIUS("Guard radius")],
    vehicles: [ON, POWER, ["SpawnChance", "integer", Math.max(1, Math.round(n.chance * 20)), 0, 100, "Spawn weight", "Weight in junkyards and trailer parks; vanilla cars sit around 1-20."], ["BoostMultiplier", "double", +(1 + n.intensity / 2).toFixed(2), 1, 4, "Boost multiplier", "Engine force while boosting."], ["Duration", "integer", n.duration, 1, 60, "Boost length (s)", "How long a boost lasts."], COOL("Boost cooldown (s)", +(n.cooldown * 4).toFixed(1))],
    worlds: [ON, POWER, ["LootMultiplier", "double", n.intensity, 0, 10, "Loot multiplier", "Scales the extra loot added to local containers."], ["HazardMinutes", "integer", n.interval * 10, 10, 240, "Minutes between anomalies", "In-game minutes between anomalies inside the zone."]],
    mechanics: [ON, POWER, ["Interval", "integer", interval, 1, 60, "Nights between events", "The event fires on every Nth night survived."], ["StartHour", "integer", 22, 0, 23, "Start hour", "In-game hour the event starts."], ["Duration", "integer", Math.max(2, Math.round(n.duration / 2)), 1, 12, "Event length (hours)", "In-game hours before it ends."], ...(horde ? ([["HordeSize", "integer", Math.round(n.health / 10), 0, 500, "Horde size", "Zombies per player on the first event night."], ["HordeCap", "integer", 400, 0, 2000, "Horde cap", "Upper bound however long the save runs."], ["SirenRadius", "integer", n.radius * 25, 10, 300, "Siren radius", "Tiles from which zombies hear the sirens."]] as Opt[]) : [])],
    quests: [ON, POWER, ["KillGoal", "integer", n.xp, 1, 500, "Kill goal", "Zombies to put down in stage two."], ["HoldMinutes", "integer", n.interval * 15, 10, 600, "Hold time (minutes)", "In-game minutes to hold the site."], ["SiteDistance", "integer", n.radius * 40, 20, 1000, "Site distance", "Tiles between the start and the site."], ["RewardXP", "integer", n.xp * 10, 0, 5000, "Reward XP", "Experience granted on completion."], RADIUS("Arrival radius")],
    interface: [ON, ["ScanRadius", "integer", n.radius * 4, 4, 60, "Scan radius", "Tiles the HUD scans for zombies."], ["DangerThreshold", "integer", n.interval, 1, 50, "Danger threshold", "Zombies in range per threat level."]],
    audio: [ON, ["ThreatRadius", "integer", n.radius * 3, 4, 60, "Threat radius", "Tiles counted when picking the layer."], ["CombatThreshold", "integer", n.interval, 1, 50, "Combat threshold", "Zombies in range that switch to the combat layer."], ["Volume", "double", 0.8, 0, 1, "Volume", "Peak gain of the music layers."], ["FadeSpeed", "double", +(0.2 + n.intensity / 4).toFixed(2), 0.05, 2, "Fade speed", "Gain per second when crossfading."]],
    shaders: [ON, ["Intensity", "double", n.intensity, 0, 2, "Intensity", "Blend between vanilla light and the grade."], ["Desaturation", "double", +(0.15 + n.chance).toFixed(2), 0, 1, "Desaturation", "How much colour drains out."], ["FogBoost", "double", +(n.chance / 2).toFixed(2), 0, 1, "Fog boost", "Extra fog on top of the weather."], ["NightOnly", "boolean", fxs.some((e) => e.key === "lunar"), 0, 0, "Night only", "Only grade between dusk and dawn."]],
  };
  const opts = OPTS[k];
  const width = Math.max(...opts.map((o) => o[0].length));

  /* ── shared/<Cls>/Config.lua: defaults + pure helpers (the part the spec tests) ── */
  const zone = { x: place.x - 40 - n.radius * 5, y: place.y - 30 - n.radius * 4, w: 80 + n.radius * 10, h: 60 + n.radius * 8 };
  const HELPERS: Record<string, string> = {
    item: code`
      --- A worn item hits at half strength.
      function Config.scaled(power, condition, maxCondition)
          if maxCondition <= 0 then return power * 0.5 end
          return power * (0.5 + 0.5 * Config.clamp(condition / maxCondition, 0, 1))
      end

      --- Linear falloff: 1 at the centre, 0 at the edge of radius.
      function Config.falloff(distance, radius)
          if radius <= 0 then return 0 end
          return Config.clamp(1 - distance / radius, 0, 1)
      end`,
    creatures: code`
      --- Rolled from the persistent outfit ID, so every client agrees on which zombie is a variant.
      function Config.isVariant(outfitId, chance)
          return outfitId ~= nil and (math.abs(outfitId) % 1000) < chance * 1000
      end

      local GAITS = { "slow", "", "sprint" }

      --- WalkType enum (1 shamble, 2 walk, 3 sprint) -> IsoZombie walk type ("slow1".."slow3", "1".."5", "sprint1".."sprint5").
      function Config.walkType(mode, seed)
          local prefix = GAITS[Config.clamp(mode, 1, 3)]
          return prefix .. tostring(math.abs(seed) % (prefix == "slow" and 3 or 5) + 1)
      end`,
    characters: code`
      function Config.canTrade(lastHours, nowHours, cooldownHours)
          return lastHours == nil or nowHours - lastHours >= cooldownHours
      end

      --- Regulars get a discount: one bill off per 100 kills, never below 1.
      function Config.price(base, kills)
          return math.max(1, base - math.floor(kills / 100))
      end`,
    vehicles: code`
      --- Boosted engine force; a wrecked engine (condition 0) gets no boost at all.
      function Config.boostForce(baseForce, multiplier, condition)
          return math.floor(baseForce * (1 + (multiplier - 1) * Config.clamp(condition / 100, 0, 1)))
      end`,
    world: code`
      -- ${place.name}: ${zone.x},${zone.y} to ${zone.x + zone.w},${zone.y + zone.h}
      Config.Zone = { name = "${cls}", x = ${zone.x}, y = ${zone.y}, z = 0, w = ${zone.w}, h = ${zone.h} }

      function Config.inZone(x, y, area)
          area = area or Config.Zone
          return x >= area.x and x < area.x + area.w and y >= area.y and y < area.y + area.h
      end`,
    mechanics: code`
      --- Night 0 never counts; after that every Interval-th night is an event night.
      function Config.isEventNight(nightsSurvived, interval)
          return interval > 0 and nightsSurvived > 0 and nightsSurvived % interval == 0
      end

      --- Every event survived adds a quarter of the base horde, up to the cap.
      function Config.hordeSize(base, nightsSurvived, interval, cap)
          local waves = math.floor(nightsSurvived / math.max(1, interval))
          return math.min(cap, base + math.max(0, waves - 1) * math.ceil(base / 4))
      end`,
    quests: code`
      Config.Stages = {
          { id = "Gear", goal = 1 },
          { id = "Cull", goal = "KillGoal" },
          { id = "Reach", goal = 1 },
          { id = "Hold", goal = "HoldMinutes" },
      }

      --- Numbers are literal goals, strings name a sandbox option.
      function Config.goal(stage)
          return type(stage.goal) == "string" and Config.get(stage.goal) or stage.goal
      end

      function Config.advance(index, progress)
          local stage = Config.Stages[index]
          if stage and progress >= Config.goal(stage) then return index + 1 end
          return index
      end`,
    interface: code`
      --- 0 calm, 1 wary, 2 danger, 3 run.
      function Config.threat(count, threshold)
          if count <= 0 then return 0 end
          return math.min(3, 1 + math.floor(count / math.max(1, threshold)))
      end`,
    audio: code`
      function Config.layerFor(zombies, isNight, threshold)
          if zombies >= threshold then return "Combat" end
          if zombies > 0 or isNight then return "Tension" end
          return "Calm"
      end

      function Config.approach(current, target, step)
          if current < target then return math.min(target, current + step) end
          return math.max(target, current - step)
      end`,
    visual: code`
      --- 1 from 22:00 to 02:00, 0 from 08:00 to 16:00, eased in between.
      function Config.nightFactor(hour)
          return Config.clamp((8 - math.min(hour, 24 - hour)) / 6, 0, 1)
      end

      function Config.lerp(a, b, t)
          return a + (b - a) * t
      end`,
  };
  const helpers = HELPERS[arch === "entity" || arch === "system" ? k : arch];

  const cfgBody = code`
    local Config = {}

    Config.MOD_ID = "${cls}"

    -- Fallbacks for when SandboxVars.${cls} is missing (main menu, pre-mod saves, unit tests).
    Config.Defaults = {
        ${opts.map((o) => `${o[0].padEnd(width)} = ${val(o)}, -- ${o[5]}`)}
    }

    --- Reads a sandbox option, falling back to the shipped default.
    function Config.get(key)
        local vars = SandboxVars and SandboxVars[Config.MOD_ID]
        local value = vars and vars[key]
        if value == nil then value = Config.Defaults[key] end
        return value
    end

    function Config.clamp(value, lo, hi)
        return math.max(lo, math.min(hi, value))
    end

    --- Real-time cooldown gate; timestamps come from getTimestampMs().
    function Config.ready(lastMs, nowMs, seconds)
        return lastMs == nil or nowMs - lastMs >= seconds * 1000
    end

    ${helpers}`;
  const cfg = lite ? cfgBody : `local Config = require("${cls}/Config")`;

  /* ── Lua building blocks ── */
  const head = (role: string) => code`
    --[[
        ${input.modName} · ${role}
        ${input.category.label} mod for Project Zomboid (Build 42) · forged by Cyrus (${MODEL_NAME[input.model]}) v${input.version}
    ]]
    ${input.version > 1 ? `-- v${input.version}: retuned defaults; every number now lives in sandbox options` : ""}`;
  const STATE = code`
    local function state(obj)
        local md = obj:getModData()
        md[MOD] = md[MOD] or {}
        return md[MOD]
    end`;
  const TXT = code`
    local function txt(key, fallback)
        return getTextOrNull("IGUI_${cls}_" .. key) or fallback
    end`;
  const REQUEST = has("world")
    ? code`
      --- Square effects (fire, thunder, spawns) are server-authoritative; in SP the command loops straight back.
      local function requestWorldFx(player, key, x, y, z)
          sendClientCommand(player, MOD, "worldFx", { key = key, x = math.floor(x), y = math.floor(y), z = math.floor(z) })
      end`
    : "";
  const COMMANDS = has("world")
    ? code`
      local Commands = {}

      function Commands.worldFx(player, args)
          local apply = WorldFx[args.key]
          local square = apply and getCell():getGridSquare(args.x, args.y, args.z)
          if not square then return end
          -- never trust a client blindly: the square has to be near the sender
          if IsoUtils.DistanceTo(player:getX(), player:getY(), args.x, args.y) > 30 then return end
          apply(square, player, Config.get("Power"))
      end

      Events.OnClientCommand.Add(function(module, command, player, args)
          if module == MOD and Commands[command] then Commands[command](player, args) end
      end)`
    : "";
  const PLAYERS = code`
    local function forEachPlayer(fn)
        local online = isServer() and getOnlinePlayers()
        if online then
            for i = 0, online:size() - 1 do fn(online:get(i)) end
            return
        end
        for i = 0, getNumActivePlayers() - 1 do
            local player = getSpecificPlayer(i)
            if player and not player:isDead() then fn(player) end
        end
    end`;
  const RING = code`
    --- A free outdoor square on a ring around (x, y), or nil after a few tries.
    local function ringSquare(x, y, minDist, maxDist)
        for _ = 1, 16 do
            local angle = ZombRandFloat(0, math.pi * 2)
            local dist = ZombRandFloat(minDist, maxDist)
            local square = getCell():getGridSquare(math.floor(x + math.cos(angle) * dist), math.floor(y + math.sin(angle) * dist), 0)
            if square and square:isFree(false) and square:isOutside() then return square end
        end
    end`;
  const params: Record<Kind, string> = { foe: "target, source, power", self: "who, power", world: "square, source, power" };
  const fxDefs = (kinds: Kind[], echo = false) => {
    const list = fxs.filter((e) => kinds.includes(FX[e.key].kind));
    const table = (e: (typeof fxs)[number]) => (FX[e.key].kind === "world" ? "WorldFx" : "Fx");
    if (!list.length) return "";
    return code`
      ${[...new Set(list.map(table))].map((t) => `local ${t} = {}`)}

      ${list
        .map(
          (e) => code`
            --- ${e.label}
            function ${table(e)}.${e.key}(${params[FX[e.key].kind]})
                ${(e.key === "summon" && echo ? ECHO : FX[e.key].lua).replaceAll("$CLS", cls).replaceAll("$NAME", name).replaceAll("$RGB", tint).replaceAll("$OUTFIT", lead.outfit)}
            end`,
        )
        .join("\n")}`;
  };
  /** Call sites; world effects default to a client request aimed at the target. */
  const calls = (kinds: Kind[], t: string, s: string, world = (key: string) => `requestWorldFx(${s}, "${key}", ${t}:getX(), ${t}:getY(), ${t}:getZ())`) =>
    fxs
      .filter((e) => kinds.includes(FX[e.key].kind))
      .map((e) => (FX[e.key].kind === "foe" ? `Fx.${e.key}(${t}, ${s}, power)` : FX[e.key].kind === "self" ? `Fx.${e.key}(${s}, power)` : world(e.key)));
  const serverHead = (role: string, requires: string[] = []) => code`
    ${head(role)}
    if isClient() then return end

    ${requires}
    ${cfg}
    local MOD = Config.MOD_ID`;
  const clientHead = (role: string, requires: string[] = []) => code`
    ${head(role)}
    ${requires}
    ${cfg}
    local MOD = Config.MOD_ID`;
  const modOptions = (id: string, label: string, key: string) => code`
    -- Build 42 mod options (Options > Mods); falls back to the default key elsewhere.
    local options = PZAPI and PZAPI.ModOptions and PZAPI.ModOptions:create(MOD, "${name}")
    if options then options:addKeyBind("${id}", ${T(id[0].toUpperCase() + id.slice(1) + "Key", label)}, Keyboard.${key}) end

    local function ${id}Key()
        local option = options and options:getOption("${id}")
        return option and option:getValue() or Keyboard.${key}
    end`;
  const sounds = (defs: [string, string, boolean][]) =>
    file(`${S}/sounds_${snake}.txt`, code`
      module Base
      {
          ${defs
            .map(([id, clip, loop]) => code`
              sound ${cls}_${id}
              {
                  category = World,
                  ${loop ? "master = Ambient,\nloop = true,\nis3D = false," : "is3D = true,"}
                  clip
                  {
                      file = media/sound/${cls}/${clip}.ogg,
                      ${loop ? "volume = 0.8," : `distanceMax = ${n.radius * 25},\nvolume = 1.0,\nreverbFactor = 0.3,`}
                  }
              }`)
            .join("\n")}
      }`);

  let core: ModFile[] = [];
  let rest: ModFile[] = [];

  /* ═════════ item: weapons · items · magic ═════════ */
  if (arch === "item") {
    const weapon = k === "weapons";
    const magic = k === "magic";
    const axe = /axe|hatchet|cleav|blade|sword|katana|machete/.test(prompt);
    const snd = axe ? "Axe" : "BaseballBat";
    const minD = +(0.6 + n.power / 14).toFixed(2);
    const props = weapon
      ? [
          "DisplayCategory = Weapon,", "Type = Weapon,", `WeaponSprite = ${cls},`, `Weight = ${(1.5 + n.radius / 4).toFixed(1)},`,
          `Categories = ${axe ? "Axe" : "Blunt"},`, "SubCategory = Swinging,", "TwoHandWeapon = TRUE,",
          `MinDamage = ${minD},`, `MaxDamage = ${+(minD + 0.5 + n.intensity / 2).toFixed(2)},`, "MinRange = 0.61,", `MaxRange = ${(1.15 + n.chance).toFixed(2)},`, "MinAngle = 0.72,",
          `SwingTime = ${(1.5 + n.cooldown / 8).toFixed(1)},`, "MinimumSwingTime = 1.5,", "SwingAmountBeforeImpact = 0.02,", "BaseSpeed = 1,",
          `MaxHitCount = ${n.radius > 6 ? 3 : 2},`, `CriticalChance = ${Math.round(n.chance * 100)},`, "CritDmgMultiplier = 2,",
          "KnockBackOnNoDeath = TRUE,", "PushBackMod = 0.3,", "KnockdownMod = 2,", "SplatNumber = 2,", "SplatBloodOnNoDeath = TRUE,",
          axe ? "DamageCategory = Slash,\nDamageMakeHole = TRUE," : "", `DoorDamage = ${Math.round(n.power)},`, `TreeDamage = ${axe ? 25 : 0},`,
          `ConditionMax = ${10 + n.interval},`, `ConditionLowerChanceOneIn = ${8 + n.interval},`,
          "SwingAnim = Bat,", "IdleAnim = Idle_Weapon2,", "RunAnim = Run_Weapon2,",
          `SwingSound = ${snd}Swing,`, `HitSound = ${snd}Hit,`, `HitFloorSound = ${snd}Hit,`, `DoorHitSound = ${snd}Hit,`, `BreakSound = ${snd}Break,`,
          `AttachmentType = ${axe ? "BigBlade" : "BigWeapon"},`,
        ]
      : magic
        ? ["DisplayCategory = Junk,", "Type = Normal,", "Weight = 0.2,", `ConditionMax = ${10 + n.interval},`, `StaticModel = ${cls},`, `WorldStaticModel = ${cls},`]
        : ["DisplayCategory = Tool,", "Type = Drainable,", `Weight = ${(0.6 + n.intensity / 2).toFixed(1)},`, `UseDelta = ${(1 / (n.interval + 4)).toFixed(3)},`, "UseWhileEquipped = FALSE,", "cantBeConsolided = TRUE,", `StaticModel = ${cls},`, `WorldStaticModel = ${cls},`];
    const mesh = weapon ? `Weapons/2Handed/${cls}` : `WorldItems/${cls}`;
    const script = file(`${S}/items_${snake}.txt`, code`
      module Base
      {
          item ${cls}
          {
              DisplayName = ${name},
              Icon = ${cls},
              ${props}
          }

          /* mesh: common/media/models_X/${mesh}.fbx · texture: common/media/textures/${mesh}.png */
          model ${cls}
          {
              mesh = ${mesh},
              texture = ${mesh},
          }
      }`);
    const skill = weapon ? "MetalWelding" : magic ? "" : "Electricity";
    const inputs = weapon
      ? ["item 1 [Base.Pipe;Base.Plank]", `item 1 [${lead.part}]`, "item 2 [Base.DuctTape]", "item 1 tags[Screwdriver] mode:keep flags[MayDegradeLight]"]
      : magic
        ? ["item 2 [Base.Twine]", `item 1 [${lead.part}]`, "item 3 [Base.RippedSheets]"]
        : ["item 2 [Base.ElectronicsScrap]", `item 1 [${lead.part}]`, "item 1 [Base.DuctTape]", "item 1 tags[Screwdriver] mode:keep flags[MayDegradeLight]"];
    const recipe = file(`${S}/recipes_${snake}.txt`, code`
      module Base
      {
          craftRecipe Make${cls}
          {
              time = ${Math.round(60 + n.cooldown * 30)},
              category = ${weapon ? "Weaponry" : magic ? "Miscellaneous" : "Electrical"},
              tags = AnySurfaceCraft,
              ${skill ? `SkillRequired = ${skill}:${Math.min(6, Math.round(n.power / 3))},\nxpAward = ${skill}:${Math.round(n.xp / 4)},` : ""}
              inputs
              {
                  ${[...new Set(inputs)].map((s) => `${s},`)}
              }
              outputs
              {
                  item 1 Base.${cls},
              }
          }
      }`);

    const actionBody = code`
      IS${cls}Action = ISBaseTimedAction:derive("IS${cls}Action")

      function IS${cls}Action:isValid()
          return self.character:getInventory():contains(self.item)${magic ? " and not self.item:isBroken()" : ""}
      end

      function IS${cls}Action:waitToStart()
          return false
      end

      function IS${cls}Action:update()
          self.item:setJobDelta(self:getJobDelta())
          self.character:setMetabolicTarget(Metabolics.LightWork)
      end

      function IS${cls}Action:start()
          self.item:setJobType(getTextOrNull("IGUI_${cls}_${magic ? "CastKey" : "Use"}") or "${magic ? "Cast" : "Activate"}")
          self.item:setJobDelta(0.0)
          self:setActionAnim(CharacterActionAnims.Craft)
          self:setOverrideHandModels(self.item, nil)
      end

      function IS${cls}Action:stop()
          self.item:setJobDelta(0.0)
          ISBaseTimedAction.stop(self)
      end

      --- Client side: visuals and the burst itself.
      function IS${cls}Action:perform()
          self.item:setJobDelta(0.0)
          ${cls}Client.release(self.character)
          ISBaseTimedAction.perform(self)
      end

      --- Build 42: authoritative state changes go in complete() (server side in MP).
      function IS${cls}Action:complete()
          ${magic ? "self.item:setCondition(math.max(0, self.item:getCondition() - 1))" : "self.item:Use()"}
          return true
      end

      function IS${cls}Action:getDuration()
          if self.character:isTimedActionInstant() then return 1 end
          return ${Math.round(40 + n.cooldown * 15)}
      end

      function IS${cls}Action:new(character, item)
          local o = ISBaseTimedAction.new(self, character)
          o.item = item
          o.stopOnWalk = ${magic ? "true" : "false"}
          o.stopOnRun = true
          o.maxTime = o:getDuration()
          return o
      end`;

    const trigger = weapon
      ? code`
        --- OnWeaponHitCharacter fires on the attacker's machine, before vanilla damage is applied.
        local function onWeaponHitCharacter(attacker, target, weapon, damage)
            if not weapon or weapon:getFullType() ~= ITEM or not Config.get("Enabled") then return end
            if not instanceof(attacker, "IsoPlayer") or not attacker:isLocalPlayer() then return end

            local power = Config.scaled(Config.get("Power"), weapon:getCondition(), weapon:getConditionMax())
            target:setHealth(target:getHealth() - power * 0.02)

            local st = state(attacker)
            local now = getTimestampMs()
            if not Config.ready(st.lastProc, now, Config.get("Cooldown")) then return end
            if ZombRandFloat(0, 1) > Config.get("Chance") then return end
            st.lastProc = now

            ${calls(["foe", "self", "world"], "target", "attacker")}
        end

        Events.OnWeaponHitCharacter.Add(onWeaponHitCharacter)`
      : code`
        ${cls}Client = ${cls}Client or {}
        local Client = ${cls}Client

        --- Hits every zombie in range, strongest at the centre, then applies the user's own effects.
        function Client.release(player)
            local radius = Config.get("Radius")
            local base = Config.get("Power")
            local zombies = getCell():getZombieList()
            local hit, nearest, best = 0, nil, radius
            for i = zombies:size() - 1, 0, -1 do
                local zombie = zombies:get(i)
                local dist = zombie:DistTo(player)
                if dist <= radius and not zombie:isDead() then
                    local power = base * Config.falloff(dist, radius)
                    ${calls(["foe"], "zombie", "player")}
                    if dist <= best then nearest, best = zombie, dist end
                    hit = hit + 1
                end
            end
            local power = base
            ${calls(["self"], "player", "player")}
            ${has("world") ? code`
              if nearest then
                  ${calls(["world"], "nearest", "player")}
              end` : ""}
            ${magic ? 'local stats = player:getStats()\nstats:setEndurance(math.max(0, stats:getEndurance() - Config.get("EnduranceCost")))' : ""}
            state(player).lastUse = getTimestampMs()
            player:setHaloNote(string.format(${T("Hit", "%d caught in the blast")}, hit), ${tint}, 250)
        end

        ${
          magic
            ? code`
              ${modOptions("cast", "Cast", "KEY_Y")}

              local function onKeyPressed(key)
                  if key ~= castKey() or not Config.get("Enabled") then return end
                  local player = getSpecificPlayer(0)
                  if not player or player:isDead() or player:getVehicle() then return end
                  local focus = player:getInventory():getFirstTypeRecurse("${cls}")
                  if not focus or focus:isBroken() then return end
                  if not Config.ready(state(player).lastUse, getTimestampMs(), Config.get("Cooldown")) then
                      player:setHaloNote(${T("Cooldown", "Still recharging")}, 180, 180, 180, 150)
                      return
                  end
                  if player:getStats():getEndurance() < Config.get("EnduranceCost") then
                      player:setHaloNote(${T("Tired", "Too exhausted to focus")}, 180, 180, 180, 150)
                      return
                  end
                  ISInventoryPaneContextMenu.transferIfNeeded(player, focus)
                  ISTimedActionQueue.add(IS${cls}Action:new(player, focus))
              end

              Events.OnKeyPressed.Add(onKeyPressed)`
            : code`
              function Client.use(item, player)
                  ISInventoryPaneContextMenu.transferIfNeeded(player, item)
                  ISTimedActionQueue.add(IS${cls}Action:new(player, item))
              end

              local function onFillInventoryObjectContextMenu(playerNum, context, items)
                  if not Config.get("Enabled") then return end
                  local player = getSpecificPlayer(playerNum)
                  for _, entry in ipairs(items) do
                      local item = instanceof(entry, "InventoryItem") and entry or entry.items[1]
                      if item and item:getFullType() == ITEM then
                          local option = context:addOption(${T("Use", "Activate")}, item, Client.use, player)
                          if not Config.ready(state(player).lastUse, getTimestampMs(), Config.get("Cooldown")) then
                              option.notAvailable = true
                              local tooltip = ISInventoryPaneContextMenu.addToolTip()
                              tooltip.description = ${T("Cooldown", "Still recharging")}
                              option.toolTip = tooltip
                          end
                          return
                      end
                  end
              end

              Events.OnFillInventoryObjectContextMenu.Add(onFillInventoryObjectContextMenu)`
        }`;

    const client = file(`${L}/client/${cls}Client.lua`, code`
      ${clientHead("client", lite && !weapon ? ['require "TimedActions/ISBaseTimedAction"'] : [])}
      local ITEM = "Base.${cls}"

      ${STATE}

      ${TXT}

      ${REQUEST}

      ${fxDefs(["foe", "self"])}

      ${trigger}

      ${lite && !weapon ? actionBody : ""}`);
    const lists = weapon ? ["GarageTools", "CrateTools", "ToolStoreTools"] : magic ? ["BedroomDresser", "BedroomSideTable", "CrateRandomJunk"] : ["CrateTools", "GarageTools", "CrateRandomJunk"];
    const server = file(`${L}/server/${cls}Server.lua`, code`
      ${serverHead("server", ['require "Items/ProceduralDistributions"'])}

      -- Container list -> base weight per roll (vanilla tools sit around 1-10).
      local LOOT = {
          ${lists.map((l, i) => `${l} = ${(n.chance * (6 - i * 2)).toFixed(1)},`)}
      }

      --- Runs right before the loot tables merge, once SandboxVars are known.
      local function addLoot()
          local scale = Config.get("LootWeight")
          for list, weight in pairs(LOOT) do
              local dist = ProceduralDistributions.list[list]
              if dist and dist.items then
                  table.insert(dist.items, "Base.${cls}")
                  table.insert(dist.items, weight * scale)
              end
          end
      end

      Events.OnPreDistributionMerge.Add(addLoot)

      ${fxDefs(["world"], true)}

      ${COMMANDS}`);
    const action = file(`${L}/client/TimedActions/IS${cls}Action.lua`, code`
      ${head("timed action")}
      require "TimedActions/ISBaseTimedAction"

      ${actionBody}`);
    core = [script, client];
    rest = weapon ? [recipe, server] : [action, recipe, server];

    /* ═════════ entity: creatures ═════════ */
  } else if (k === "creatures") {
    const client = file(`${L}/client/${cls}Zombies.lua`, code`
      ${clientHead("zombie behaviour")}
      local OUTFIT = "${lead.outfit}"

      ${STATE}

      ${REQUEST}

      ${fxDefs(["foe", "self"])}

      --- Rolled from the persistent outfit ID, so a variant stays a variant across reloads and clients.
      local function isVariant(zombie)
          local st = state(zombie)
          if st.variant == nil then
              st.variant = zombie:getOutfitName() == OUTFIT and Config.isVariant(zombie:getPersistentOutfitID(), Config.get("SpawnChance"))
          end
          return st.variant
      end

      local function awaken(zombie, st)
          st.awake = true
          zombie:setWalkType(Config.walkType(Config.get("WalkType"), zombie:getPersistentOutfitID()))
          zombie:setHealth(Config.get("Health"))
      end

      --- OnZombieUpdate runs every tick for every loaded zombie: bail out early and cheaply.
      local function onZombieUpdate(zombie)
          if not isVariant(zombie) then return end
          local st = state(zombie)
          if not st.awake then awaken(zombie, st) end

          local target = zombie:getTarget()
          if not target or not instanceof(target, "IsoPlayer") or not target:isLocalPlayer() then return end
          if zombie:DistTo(target) > Config.get("Radius") then return end

          local now = getTimestampMs()
          if not Config.ready(st.lastAbility, now, Config.get("Cooldown")) then return end
          st.lastAbility = now

          local power = Config.get("Power")
          ${calls(["foe", "self", "world"], "target", "zombie", (key) => `requestWorldFx(target, "${key}", zombie:getX(), zombie:getY(), zombie:getZ())`)}
          -- the shriek: everything in earshot turns toward the fight
          getWorldSoundManager():addSound(zombie, math.floor(zombie:getX()), math.floor(zombie:getY()), math.floor(zombie:getZ()), math.floor(power * 3), 50)
      end

      Events.OnZombieUpdate.Add(onZombieUpdate)`);
    const server = file(`${L}/server/${cls}Server.lua`, code`
      ${serverHead("server")}
      local OUTFIT = "${lead.outfit}"
      local DROP = "${lead.drop}"

      ${PLAYERS}

      ${RING}

      ${fxDefs(["world"])}

      local function isVariant(zombie)
          local st = zombie:getModData()[MOD]
          if st and st.variant ~= nil then return st.variant end
          return zombie:getOutfitName() == OUTFIT and Config.isVariant(zombie:getPersistentOutfitID(), Config.get("SpawnChance"))
      end

      --- Packs only hunt at night: spawned out of sight, then pathed toward the player.
      local function onEveryHours()
          if not Config.get("Enabled") then return end
          local hour = getGameTime():getHour()
          if hour > 4 and hour < 21 then return end
          forEachPlayer(function(player)
              if ZombRandFloat(0, 1) > Config.get("SpawnChance") then return end
              local square = ringSquare(player:getX(), player:getY(), 30, 50)
              if not square then return end
              local pack = addZombiesInOutfit(square:getX(), square:getY(), 0, Config.get("PackSize"), OUTFIT, 50)
              for i = 0, pack:size() - 1 do
                  local zombie = pack:get(i)
                  zombie:getModData()[MOD] = { variant = true }
                  zombie:pathToSound(math.floor(player:getX()), math.floor(player:getY()), 0)
              end
          end)
      end

      local function onZombieDead(zombie)
          if isVariant(zombie) and ZombRandFloat(0, 1) < Config.get("DropChance") then
              zombie:getInventory():AddItem(DROP)
          end
      end

      Events.EveryHours.Add(onEveryHours)
      Events.OnZombieDead.Add(onZombieDead)

      ${COMMANDS}`);
    core = [client];
    rest = [server];

    /* ═════════ entity: characters (survivor NPC on a pacified IsoZombie) ═════════ */
  } else if (k === "characters") {
    const npcName = input.modName.split(" ").slice(-1)[0].replace(/["\\]/g, "");
    const goods = [...new Set([...fxs.map((e) => FX[e.key].drop), "Base.TinnedBeans"])];
    const server = file(`${L}/server/${cls}Server.lua`, code`
      ${serverHead("server")}
      local OUTFIT = "${lead.outfit}"

      ${PLAYERS}

      ${RING}

      ${fxDefs(["foe", "self"])}

      ${fxDefs(["world"], true)}

      local function data()
          return ModData.getOrCreate(MOD)
      end

      --- The persistent outfit ID survives chunk reloads; zombie mod data does not.
      local function isNpc(zombie)
          local id = data().npcOutfitId
          return id ~= nil and zombie:getPersistentOutfitID() == id
      end

      local function findNpc()
          local zombies = getCell():getZombieList()
          for i = 0, zombies:size() - 1 do
              if isNpc(zombies:get(i)) then return zombies:get(i) end
          end
      end

      --- The classic NPC trick: a useless, toothless, invincible zombie in a survivor outfit.
      local function pacify(npc)
          npc:setUseless(true)
          npc:setNoTeeth(true)
          npc:setInvincible(true)
          npc:setTarget(nil)
      end

      local function spawn(d)
          local list = addZombiesInOutfit(d.home.x, d.home.y, d.home.z, 1, OUTFIT, ${hashStr(npcName) % 2 ? 100 : 0})
          if list:size() == 0 then return nil end
          local npc = list:get(0)
          pacify(npc)
          d.npcOutfitId = npc:getPersistentOutfitID()
          ModData.transmit(MOD)
          return npc
      end

      --- Zombies that wander into ${npcName}'s yard get dealt with.
      local function guard(npc)
          local power = Config.get("Power")
          local radius = Config.get("Radius")
          local zombies = getCell():getZombieList()
          local nearest, best = nil, radius
          for i = zombies:size() - 1, 0, -1 do
              local zombie = zombies:get(i)
              local dist = zombie ~= npc and not zombie:isDead() and zombie:DistTo(npc) or radius + 1
              if dist <= radius then
                  ${calls(["foe"], "zombie", "npc")}
                  if dist <= best then nearest, best = zombie, dist end
              end
          end
          if not nearest then return end
          ${calls(["self", "world"], "nearest", "npc", (key) => `WorldFx.${key}(nearest:getCurrentSquare(), npc, power)`)}
      end

      local function onEveryTenMinutes()
          if not Config.get("Enabled") then return end
          local d = data()
          if not d.home then
              forEachPlayer(function(player)
                  local square = not d.home and ringSquare(player:getX(), player:getY(), 6, 12)
                  if square then d.home = { x = square:getX(), y = square:getY(), z = square:getZ() } end
              end)
              if not d.home then return end
              ModData.transmit(MOD)
          end
          local npc = findNpc()
          if not npc then
              local nearby = false
              forEachPlayer(function(player)
                  nearby = nearby or IsoUtils.DistanceTo(player:getX(), player:getY(), d.home.x, d.home.y) < 40
              end)
              npc = nearby and spawn(d) or nil
          end
          if npc then
              pacify(npc)
              guard(npc)
          end
      end

      Events.EveryTenMinutes.Add(onEveryTenMinutes)`);
    const client = file(`${L}/client/${cls}Client.lua`, code`
      ${clientHead("client")}

      ${cls}Client = ${cls}Client or {}
      local Client = ${cls}Client
      local GOODS = { ${goods.map((g) => `"${g}"`).join(", ")} }

      ${STATE}

      ${TXT}

