          local text = { "<SIZE:medium> ${name} <LINE> <SIZE:small> <LINE> " }
          for i, stage in ipairs(Config.Stages) do
              local color = i < st.stage and "<RGB:0.5,0.8,0.5>" or i == st.stage and "<RGB:1,0.85,0.4>" or "<RGB:0.45,0.45,0.45>"
              local label = string.format(txt("Stage" .. stage.id, stage.id), getItemNameFromFullType(GEAR))
              local count = i == st.stage and string.format(" (%d/%d)", st.progress or 0, Config.goal(stage)) or ""
              table.insert(text, color .. " " .. label .. count .. " <LINE> ")
          end
          if st.done then table.insert(text, "<LINE> <RGB:0.5,1,0.6> " .. ${T("Done", "Complete. Stay alive out there.")}) end
          return table.concat(text)
      end

      local function finish(player, st)
          st.done = true
          player:getXp():AddXP(Perks.${perk}, Config.get("RewardXP"))
          player:getInventory():AddItem(REWARD)
          local power = Config.get("Power")
          ${calls(["self"], "player", "player")}
          local zombies = getCell():getZombieList()
          for i = zombies:size() - 1, 0, -1 do
              local zombie = zombies:get(i)
              if zombie:DistTo(player) <= Config.get("Radius") * 2 then
                  ${calls(["foe"], "zombie", "player")}
              end
          end
          player:setHaloNote(${T("Reward", "Quest complete")}, 120, 255, 140, 500)
      end

      function Quest.update(player)
          local st = state(player)
          if not st.stage then
              st.stage = 1
              site(player, st)
          end
          if st.done then return end
          st.progress = Objectives[Config.Stages[st.stage].id](player, st)
          local nextStage = Config.advance(st.stage, st.progress)
          if nextStage ~= st.stage then
              st.stage, st.progress, st.killsAtStart, st.held = nextStage, 0, player:getZombieKills(), 0
              if nextStage > #Config.Stages then
                  finish(player, st)
              else
                  player:setHaloNote(txt("Stage" .. Config.Stages[nextStage].id, ""), 255, 220, 120, 300)
              end
          end
          if Quest.journal and Quest.journal.player == player then Quest.journal:refresh(Quest.describe(player, st)) end
      end

      ${modOptions("journal", "Quest journal", "KEY_J")}

      local function onKeyPressed(key)
          if key ~= journalKey() then return end
          local player = getSpecificPlayer(0)
          if not player then return end
          if Quest.journal and Quest.journal:isVisible() then
              Quest.journal:close()
              return
          end
          Quest.journal = Quest.journal or ${cls}Journal:new(80, 120, 340, 260, player)
          Quest.journal:addToUIManager()
          Quest.journal:setVisible(true)
          Quest.update(player)
      end

      Events.EveryOneMinute.Add(function()
          if not Config.get("Enabled") then return end
          for i = 0, getNumActivePlayers() - 1 do
              local player = getSpecificPlayer(i)
              if player and not player:isDead() then Quest.update(player) end
          end
      end)
      Events.OnKeyPressed.Add(onKeyPressed)`);
    T("StageGear", "Find: %s");
    T("StageCull", "Thin the dead around you");
    T("StageReach", "Reach the site on your map");
    T("StageHold", "Hold the site");
    const journal = file(`${L}/client/ISUI/${cls}Journal.lua`, code`
      ${head("journal window")}
      require "ISUI/ISCollapsableWindow"
      require "ISUI/ISRichTextPanel"

      ${cls}Journal = ISCollapsableWindow:derive("${cls}Journal")

      function ${cls}Journal:createChildren()
          ISCollapsableWindow.createChildren(self)
          local top = self:titleBarHeight()
          self.body = ISRichTextPanel:new(0, top, self.width, self.height - top)
          self.body:initialise()
          self.body.autosetheight = false
          self.body.clip = true
          self.body.marginLeft = 12
          self.body.marginTop = 8
          self.body.marginRight = 12
          self.body.background = false
          self:addChild(self.body)
          self.body:addScrollBars()
      end

      function ${cls}Journal:refresh(text)
          self.body.text = text
          self.body:paginate()
      end

      function ${cls}Journal:close()
          self:setVisible(false)
          self:removeFromUIManager()
      end

      function ${cls}Journal:new(x, y, width, height, player)
          local o = ISCollapsableWindow.new(self, x, y, width, height)
          o.player = player
          o.title = getTextOrNull("IGUI_${cls}_Title") or "${name}"
          o.resizable = false
          o.backgroundColor = { r = 0.06, g = 0.05, b = 0.04, a = 0.88 }
          return o
      end`);
    core = [quest, journal];

    /* ═════════ system: interface (HUD) ═════════ */
  } else if (k === "interface") {
    const neon = fxs.some((e) => e.key === "neon");
    const rows = [["Time", FX.lunar.hud[1]] as [string, string], ...fxs.map((e) => FX[e.key].hud), ["Kills", FX.summon.hud[1]] as [string, string]].filter((r, i, all) => all.findIndex((x) => x[0] === r[0]) === i).slice(0, 4);
    const [r, g, b] = fxs[0].tint;
    const hud = file(`${L}/client/ISUI/${cls}HUD.lua`, code`
      ${head("HUD panel")}
      require "ISUI/ISPanel"
      ${neon ? 'require "ISUI/ISRichTextPanel"' : ""}

      ${cls}HUD = ISPanel:derive("${cls}HUD")

      local FONT = UIFont.Small
      local LINE = getTextManager():getFontHeight(FONT) + 2
      local THREAT = {
          [0] = { 0.55, 0.85, 0.55 },
          { 0.95, 0.85, 0.35 },
          { 1.0, 0.55, 0.2 },
          { 1.0, 0.25, 0.25 },
      }
      local ROWS = {
          ${rows.map(([label, expr]) => `{ getTextOrNull("IGUI_${cls}_${label.replace(/ /g, "")}") or "${label}", function(player) return ${expr} end },`)}
      }

      function ${cls}HUD:scan()
          local count = 0
          local zombies = getCell():getZombieList()
          for i = 0, zombies:size() - 1 do
              local zombie = zombies:get(i)
              if not zombie:isDead() and zombie:DistTo(self.player) <= self.scanRadius then count = count + 1 end
          end
          ${neon ? "if self.threatOf(count) ~= self.threatOf(self.zombies) then self:log(count) end" : ""}
          self.zombies = count
      end
      ${neon ? code`

        function ${cls}HUD:log(count)
            local c = THREAT[self.threatOf(count)]
            table.insert(self.lines, 1, string.format("<RGB:%.2f,%.2f,%.2f> %02d:%02d  %d in range <LINE> ", c[1], c[2], c[3], getGameTime():getHour(), getGameTime():getMinutes(), count))
            if #self.lines > 4 then table.remove(self.lines) end
            self.feed.text = table.concat(self.lines)
            self.feed:paginate()
        end` : ""}

      --- Scanning is throttled to twice a second; prerender runs every frame.
      function ${cls}HUD:prerender()
          ISPanel.prerender(self)
          local now = getTimestampMs()
          if now >= self.nextScan then
              self:scan()
              self.nextScan = now + 500
          end
      end

      function ${cls}HUD:render()
          local player = self.player
          if not player or player:isDead() then return end
          local c = THREAT[self.threatOf(self.zombies)]
          self:drawText(getTextOrNull("IGUI_${cls}_Title") or "${name}", 10, 6, ${r}, ${g}, ${b}, 1, FONT)
          self:drawTextRight(tostring(self.zombies), self.width - 10, 6, c[1], c[2], c[3], 1, FONT)
          local fill = math.min(1, self.zombies / (self.threshold * 3))
          self:drawRect(10, LINE + 8, self.width - 20, 5, 0.6, 0.15, 0.15, 0.15)
          self:drawRect(10, LINE + 8, (self.width - 20) * fill, 5, 0.95, c[1], c[2], c[3])
          local y = LINE + 20
          for _, row in ipairs(ROWS) do
              self:drawText(row[1], 10, y, 0.65, 0.65, 0.65, 1, FONT)
              self:drawTextRight(row[2](player), self.width - 10, y, 1, 1, 1, 1, FONT)
              y = y + LINE
          end
      end
      ${neon ? code`

        function ${cls}HUD:createChildren()
            ISPanel.createChildren(self)
            self.feed = ISRichTextPanel:new(0, self.height - LINE * 4 - 6, self.width, LINE * 4)
            self.feed:initialise()
            self.feed.background = false
            self.feed.autosetheight = false
            self:addChild(self.feed)
        end` : ""}

      --- opts: scanRadius, threshold, threatOf(count) -> 0..3 (all from Config, so this file stays UI-only).
      function ${cls}HUD:new(x, y, player, opts)
          local o = ISPanel.new(self, x, y, 220, LINE * ${rows.length + (neon ? 4 : 0)} + LINE + 28)
          o.player = player
          o.scanRadius = opts.scanRadius
          o.threshold = opts.threshold
          o.threatOf = opts.threatOf
          o.zombies = 0
          o.nextScan = 0
          o.lines = {}
          o.moveWithMouse = true
          o.backgroundColor = { r = 0.04, g = 0.04, b = 0.05, a = 0.72 }
          o.borderColor = { r = ${r}, g = ${g}, b = ${b}, a = 0.8 }
          return o
      end`);
    const client = file(`${L}/client/${cls}Client.lua`, code`
      ${clientHead("client", [`require "ISUI/${cls}HUD"`])}
      local huds = {}

      ${TXT}

      ${modOptions("toggle", "Toggle HUD", "KEY_H")}

      local function create(playerNum, player)
          if huds[playerNum] then huds[playerNum]:removeFromUIManager() end
          local x = getPlayerScreenLeft(playerNum) + getPlayerScreenWidth(playerNum) - 240
          local y = getPlayerScreenTop(playerNum) + 120
          local hud = ${cls}HUD:new(x, y, player, {
              scanRadius = Config.get("ScanRadius"),
              threshold = Config.get("DangerThreshold"),
              threatOf = function(count) return Config.threat(count, Config.get("DangerThreshold")) end,
          })
          hud:initialise()
          hud:addToUIManager()
          hud:setVisible(Config.get("Enabled"))
          huds[playerNum] = hud
      end

      local function onKeyPressed(key)
          local hud = huds[0]
          if key == toggleKey() and hud then hud:setVisible(not hud:isVisible()) end
      end

      Events.OnCreatePlayer.Add(create)
      Events.OnKeyPressed.Add(onKeyPressed)
      Events.OnPlayerDeath.Add(function(player)
          local hud = huds[player:getPlayerNum()]
          if hud then hud:removeFromUIManager() end
          huds[player:getPlayerNum()] = nil
      end)`);
    rows.forEach(([label]) => ui.set(label.replace(/ /g, ""), label));
    core = [client, hud];

    /* ═════════ system: audio (adaptive layers) ═════════ */
  } else if (k === "audio") {
    const client = file(`${L}/client/${cls}Client.lua`, code`
      ${clientHead("adaptive soundtrack")}
      local LAYERS = { Calm = "${cls}_Calm", Tension = "${cls}_Tension", Combat = "${cls}_Combat" }
      local current = { layer = nil, audio = nil, gain = 0 }
      local fading = {}

      local function zombiesNear(player, radius)
          local count = 0
          local zombies = getCell():getZombieList()
          for i = 0, zombies:size() - 1 do
              local zombie = zombies:get(i)
              if not zombie:isDead() and zombie:DistTo(player) <= radius then count = count + 1 end
          end
          return count
      end

      --- Picks the layer once per in-game minute; the crossfade itself happens in OnTick.
      local function evaluate()
          local player = getSpecificPlayer(0)
          if not player or player:isDead() or not Config.get("Enabled") then return end
          local hour = getGameTime():getHour()
          local zombies = zombiesNear(player, Config.get("ThreatRadius"))
          local layer = Config.layerFor(zombies, hour >= 21 or hour < 5, Config.get("CombatThreshold"))
          if layer == current.layer then return end
          if current.audio then table.insert(fading, { audio = current.audio, gain = current.gain }) end
          current.layer, current.gain = layer, 0
          current.audio = getSoundManager():PlaySound(LAYERS[layer], true, 0.0)
          if layer == "Combat" then getSoundManager():playUISound("${cls}_Stinger") end
      end

      local function onTick()
          local step = Config.get("FadeSpeed") * getGameTime():getRealworldSecondsSinceLastUpdate()
          if current.audio then
              current.gain = Config.approach(current.gain, Config.get("Volume") * getCore():getOptionMusicVolume() / 10, step)
              current.audio:setVolume(current.gain)
          end
          for i = #fading, 1, -1 do
              local f = fading[i]
              f.gain = Config.approach(f.gain, 0, step)
              f.audio:setVolume(f.gain)
              if f.gain <= 0 then
                  f.audio:stop()
                  table.remove(fading, i)
              end
          end
      end

      Events.EveryOneMinute.Add(evaluate)
      Events.OnTick.Add(onTick)
      Events.OnPlayerDeath.Add(function()
          if current.audio then current.audio:stop() end
          current.layer, current.audio = nil, nil
      end)`);
    core = [client, sounds([["Calm", "calm", true], ["Tension", "tension", true], ["Combat", "combat", true], ["Stinger", "stinger", false]])];

    /* ═════════ visual: climate-driven colour grade ═════════ */
  } else {
    const [r, g, b] = fxs[0].tint;
    const client = file(`${L}/client/${cls}Client.lua`, code`
      ${clientHead("colour grade")}
      local TINT = { ${r}, ${g}, ${b} }
      local climate, floats, light

      local options = PZAPI and PZAPI.ModOptions and PZAPI.ModOptions:create(MOD, "${name}")
      if options then options:addTickBox("grade", ${T("Grade", "Enable colour grade")}, true) end

      local function enabled()
          local option = options and options:getOption("grade")
          return Config.get("Enabled") and (not option or option:getValue())
      end

      --- Grab the climate floats once; setEnableModded hands them to us without touching saves.
      local function bind()
          climate = getClimateManager()
          floats = {
              desaturation = climate:getClimateFloat(ClimateManager.FLOAT_DESATURATION),
              fog = climate:getClimateFloat(ClimateManager.FLOAT_FOG_INTENSITY),
              light = climate:getClimateFloat(ClimateManager.FLOAT_GLOBAL_LIGHT_INTENSITY),
          }
          light = climate:getClimateColor(ClimateManager.COLOR_GLOBAL_LIGHT)
          for _, f in pairs(floats) do f:setEnableModded(true) end
          light:setEnableModded(true)
      end

      local function apply()
          if not climate then return end
          local night = Config.nightFactor(getGameTime():getTimeOfDay())
          local strength = enabled() and Config.get("Intensity") * (Config.get("NightOnly") and night or 1) or 0
          local blend = Config.clamp(strength, 0, 1)
          local wet = climate:getPrecipitationIntensity()

          floats.desaturation:setModdedValue(Config.clamp(Config.get("Desaturation") + wet * 0.2, 0, 1))
          floats.desaturation:setModdedInterpolate(blend)
          floats.fog:setModdedValue(Config.clamp(climate:getFogIntensity() + Config.get("FogBoost"), 0, 1))
          floats.fog:setModdedInterpolate(blend)
          floats.light:setModdedValue(Config.lerp(0.85, 0.6, night))
          floats.light:setModdedInterpolate(blend * 0.5)

          local a = Config.lerp(0.25, 0.6, night)
          light:setModdedValue(ClimateColorInfo.new(TINT[1], TINT[2], TINT[3], a, TINT[1], TINT[2], TINT[3], a))
          light:setModdedInterpolate(blend * 0.6)
      end

      Events.OnGameStart.Add(function()
          bind()
          apply()
      end)
      Events.EveryOneMinute.Add(apply)`);
    core = [client];
  }

  /* ── manifest, config, translations, test ── */
  const features = deriveFeatures(input);
  const modInfo = file("42/mod.info", code`
    name=${input.modName}
    id=${cls}
    author=Cyrus
    description=${features.join(". ")}.
    poster=poster.png
