  const igui = file("common/media/lua/shared/Translate/EN/IG_UI_EN.txt", code`
    IG_UI_EN = {
        ${[...ui].map(([key, text]) => `IGUI_${cls}_${key} = "${text}",`)}
    }`);
  const files = lite ? [...core, modInfo] : [...core, ...rest, configLua, modInfo, ...(ui.size > 1 ? [igui] : [])];

  const config = file("42/media/sandbox-options.txt", code`
