    local options = PZAPI and PZAPI.ModOptions and PZAPI.ModOptions:create(MOD, "${name}")
    if options then options:addKeyBind("${id}", ${T(`${id}Key`, label)}, Keyboard.${key}) end
    local function ${id}Key()
        local option = options and options:getOption("${id}")
        return option and option:getValue() or Keyboard.${key}
    end`;
  const sounds = (defs: [string, boolean][]) =>
    file(`${S}/sounds_${snake}.txt`, blk("module Base", defs.flatMap(([id, loop], i) => [i ? GAP : false, blk(`sound ${cls}_${id}`, [
      ...kv(loop ? { category: "World", master: "Ambient", loop: true, is3D: false } : { category: "World", is3D: true }),
      blk("clip", kv({ file: `media/sound/${cls}/${id.toLowerCase()}.ogg`, ...(loop ? { volume: 0.8 } : { distanceMax: n.radius * 25, volume: "1.0", reverbFactor: 0.3 }) })),
    ])])));

  let core: ModFile[] = [];
