    const skill = weapon ? "MetalWelding" : magic ? "" : "Electricity";
    const inputs = weapon
      ? ["item 1 [Base.Pipe;Base.Plank]", `item 1 [${lead.part}]`, "item 2 [Base.DuctTape]", "item 1 tags[Screwdriver] mode:keep flags[MayDegradeLight]"]
      : magic
        ? ["item 2 [Base.Twine]", `item 1 [${lead.part}]`, "item 3 [Base.RippedSheets]"]
