    const recipe = file(`${S}/recipes_${snake}.txt`, blk("module Base", [blk(`craftRecipe Make${cls}`, [
      ...kv({ time: Math.round(60 + n.cooldown * 30), category: weapon ? "Weaponry" : magic ? "Miscellaneous" : "Electrical", tags: "AnySurfaceCraft" }),
      ...(skill ? kv({ SkillRequired: `${skill}:${Math.min(6, Math.round(n.power / 3))}`, xpAward: `${skill}:${Math.round(n.xp / 4)}` }) : []),
      blk("inputs", [...new Set(inputs)].map((s) => `${s},`)),
      blk("outputs", [`item 1 Base.${cls},`]),
    ])]));

    const trigger = weapon
      ? code`
        --- Fires on the attacker's machine, before vanilla damage is applied.
        local function onWeaponHitCharacter(attacker, target, weapon, damage)
            if not weapon or weapon:getFullType() ~= ITEM or not Config.get("Enabled") then return end
            if not instanceof(attacker, "IsoPlayer") or not attacker:isLocalPlayer() then return end
            local power = Config.scaled(Config.get("Power"), weapon:getCondition(), weapon:getConditionMax())
            target:setHealth(target:getHealth() - power * 0.02)

            local st, now = state(attacker), getTimestampMs()
            if not Config.ready(st.lastProc, now, Config.get("Cooldown")) or ZombRandFloat(0, 1) > Config.get("Chance") then return end
            st.lastProc = now
            ${calls(["foe", "self", "world"], "target", "attacker")}
        end

        Events.OnWeaponHitCharacter.Add(onWeaponHitCharacter)`
      : code`
        ${cls}Client = ${cls}Client or {}
        local Client = ${cls}Client

        --- Hits every zombie in range, strongest at the centre, then applies the user's own effects.
        function Client.release(player)
            local radius, base = Config.get("Radius"), Config.get("Power")
            local zombies = getCell():getZombieList()
            local hit, nearest, best = 0, nil, radius
            for i = zombies:size() - 1, 0, -1 do
                local zombie = zombies:get(i)
                local dist = zombie:DistTo(player)
                if dist <= radius and not zombie:isDead() then
                    local power = base * Config.falloff(dist, radius)
                    ${calls(["foe"], "zombie", "player")}
                    if dist <= best then nearest, best = zombie, dist end
                    hit = hit + 1
                end
            end
            local power = base
            ${calls(["self"], "player", "player")}
            ${has("world") ? code`
              if nearest then
                  ${calls(["world"], "nearest", "player")}
              end` : ""}
            ${magic ? 'player:getStats():setEndurance(math.max(0, player:getStats():getEndurance() - Config.get("EnduranceCost")))' : ""}
            state(player).lastUse = getTimestampMs()
            player:setHaloNote(string.format(${T("Hit", "%d caught in the blast")}, hit), ${tint}, 250)
        end

        ${magic
          ? code`
            ${keyBind("cast", "Cast", "KEY_Y")}

            local function onKeyPressed(key)
                if key ~= castKey() or not Config.get("Enabled") then return end
                local player = getSpecificPlayer(0)
                local focus = player and not player:getVehicle() and player:getInventory():getFirstTypeRecurse("${cls}")
                if not focus or focus:isBroken() then return end
                if not Config.ready(state(player).lastUse, getTimestampMs(), Config.get("Cooldown")) then
                    return player:setHaloNote(${T("Cooldown", "Still recharging")}, 180, 180, 180, 150)
                end
                if player:getStats():getEndurance() < Config.get("EnduranceCost") then
                    return player:setHaloNote(${T("Tired", "Too exhausted to focus")}, 180, 180, 180, 150)
                end
                ISInventoryPaneContextMenu.transferIfNeeded(player, focus)
                ISTimedActionQueue.add(IS${cls}Action:new(player, focus))
            end

            Events.OnKeyPressed.Add(onKeyPressed)`
          : code`
            function Client.use(item, player)
                ISInventoryPaneContextMenu.transferIfNeeded(player, item)
                ISTimedActionQueue.add(IS${cls}Action:new(player, item))
            end

            local function onFillInventoryObjectContextMenu(playerNum, context, items)
                local player = getSpecificPlayer(playerNum)
                for _, entry in ipairs(items) do
                    local item = instanceof(entry, "InventoryItem") and entry or entry.items[1]
                    if item and item:getFullType() == ITEM and Config.get("Enabled") then
                        local option = context:addOption(${T("Use", "Activate")}, item, Client.use, player)
                        if not Config.ready(state(player).lastUse, getTimestampMs(), Config.get("Cooldown")) then
                            option.notAvailable = true
                            option.toolTip = ISInventoryPaneContextMenu.addToolTip()
                            option.toolTip.description = ${T("Cooldown", "Still recharging")}
                        end
                        return
                    end
                end
            end

            Events.OnFillInventoryObjectContextMenu.Add(onFillInventoryObjectContextMenu)`}

        -- Timed action ------------------------------------------------------------
        IS${cls}Action = ISBaseTimedAction:derive("IS${cls}Action")

        function IS${cls}Action:isValid() return self.character:getInventory():contains(self.item) end
        function IS${cls}Action:waitToStart() return false end

        function IS${cls}Action:update()
            self.item:setJobDelta(self:getJobDelta())
            self.character:setMetabolicTarget(Metabolics.LightWork)
        end

        function IS${cls}Action:start()
            self.item:setJobType(${say(magic ? "Casting" : "Use", magic ? "Channelling" : "Activate")})
            self:setActionAnim(CharacterActionAnims.Craft)
            self:setOverrideHandModels(self.item, nil)
        end

        function IS${cls}Action:stop()
            self.item:setJobDelta(0.0)
            ISBaseTimedAction.stop(self)
        end

        function IS${cls}Action:perform()
