        end`;
    const client = file(`${L}/client/${cls}Client.lua`, code`
      ${head("client", weapon ? [] : ['require "TimedActions/ISBaseTimedAction"'])}
      local ITEM = "Base.${cls}"

      ${STATE}
      ${weapon ? "" : TXT}

      ${REQUEST}

      ${fxDefs(["foe", "self"])}

      ${trigger}`);
    const lists = weapon ? ["GarageTools", "CrateTools", "ToolStoreTools"] : magic ? ["BedroomDresser", "BedroomSideTable", "CrateRandomJunk"] : ["CrateTools", "GarageTools", "CrateRandomJunk"];
    const server = file(`${L}/server/${cls}Server.lua`, code`
      ${head("server", ['require "Items/ProceduralDistributions"'], "server")}

      -- Container list -> base weight per roll (vanilla tools sit around 1-10).
      local LOOT = { ${lists.map((l, i) => `${l} = ${(n.chance * (6 - i * 2)).toFixed(1)}`).join(", ")} }

      --- Runs right before the loot tables merge, once SandboxVars are known.
      Events.OnPreDistributionMerge.Add(function()
          for list, weight in pairs(LOOT) do
              local dist = ProceduralDistributions.list[list]
              if dist and dist.items then
                  table.insert(dist.items, "Base.${cls}")
                  table.insert(dist.items, weight * Config.get("LootWeight"))
              end
          end
