      end

      Events.OnZombieUpdate.Add(onZombieUpdate)`);
    const server = file(`${L}/server/${cls}Server.lua`, code`
      ${head("server", [], "server")}
      local OUTFIT, DROP = "${lead.outfit}", "${lead.drop}"

      ${PLAYERS}

      ${fxDefs(["world"])}

      local function isVariant(zombie)
          local st = zombie:getModData()[MOD]
          if st and st.variant ~= nil then return st.variant end
          return zombie:getOutfitName() == OUTFIT and Config.isVariant(zombie:getPersistentOutfitID(), Config.get("SpawnChance"))
      end

      --- Packs only hunt at night: spawned out of sight, then pathed toward the player.
      Events.EveryHours.Add(function()
          local hour = getGameTime():getHour()
          if not Config.get("Enabled") or (hour > 4 and hour < 21) then return end
          forEachPlayer(function(player)
              local square = ZombRandFloat(0, 1) < Config.get("SpawnChance") and ringSquare(player:getX(), player:getY(), 30, 50)
              if not square then return end
              local pack = addZombiesInOutfit(square:getX(), square:getY(), 0, Config.get("PackSize"), OUTFIT, 50)
              for i = 0, pack:size() - 1 do
                  pack:get(i):getModData()[MOD] = { variant = true }
                  pack:get(i):pathToSound(math.floor(player:getX()), math.floor(player:getY()), 0)
              end
          end)
      end)

