    core = [client];
    rest = [server];
  } else if (k === "characters") {
    /* ═════════ characters: survivor NPC on a pacified IsoZombie ═════════ */
    const npc = input.modName.split(" ").slice(-1)[0].replace(/["\\]/g, "");
    const goods = [...new Set([...fxs.map((e) => FX[e.key].drop), "Base.TinnedBeans"])];
    const server = file(`${L}/server/${cls}Server.lua`, code`
      ${head("server", [], "server")}
      local OUTFIT = "${lead.outfit}"

      ${PLAYERS}

      ${fxDefs(["foe"])}

      ${fxDefs(["world"], true)}

      local function data() return ModData.getOrCreate(MOD) end

      --- The persistent outfit ID survives chunk reloads; zombie mod data does not.
      local function findNpc()
          local id, zombies = data().npcOutfitId, getCell():getZombieList()
          for i = 0, id and zombies:size() - 1 or -1 do
              if zombies:get(i):getPersistentOutfitID() == id then return zombies:get(i) end
          end
      end

      --- The classic NPC trick: a useless, toothless, invincible zombie in a survivor outfit.
      local function pacify(npc)
          npc:setUseless(true)
          npc:setNoTeeth(true)
          npc:setInvincible(true)
          npc:setTarget(nil)
          return npc
      end

      local function spawn(d)
          local list = addZombiesInOutfit(d.home.x, d.home.y, d.home.z, 1, OUTFIT, ${hashStr(npc) % 2 ? 100 : 0})
          if list:size() == 0 then return nil end
          d.npcOutfitId = list:get(0):getPersistentOutfitID()
          ModData.transmit(MOD)
          return pacify(list:get(0))
      end

      --- Zombies that wander into ${npc}'s yard get dealt with.
      local function guard(npc)
          local power, radius = Config.get("Power"), Config.get("Radius")
