              forEachPlayer(function(player)
                  if not npc and IsoUtils.DistanceTo(player:getX(), player:getY(), d.home.x, d.home.y) < 40 then npc = spawn(d) end
              end)
          end
          if npc then guard(pacify(npc)) end
      end)`);
    const client = file(`${L}/client/${cls}Client.lua`, code`
