          for x = square:getX() - 1, square:getX() + 1 do
              for y = square:getY() - 1, square:getY() + 1 do
                  local movers = getCell():getGridSquare(x, y, square:getZ()) and getCell():getGridSquare(x, y, square:getZ()):getMovingObjects()
                  for i = 0, movers and movers:size() - 1 or -1 do
