          local option = sub:addOption(string.format(${T("Trade", "Trade (%d bills)")}, price(player)), player, trade, npc)
          option.notAvailable = not Config.canTrade(state(player).lastTrade, getGameTime():getWorldAgeHours(), Config.get("TradeCooldown"))
          sub:addOption(${T("Chat", "Ask for news")}, player, chat, npc)
      end)

      -- MP: the server owns the NPC's identity; mirror its global mod data.
      Events.OnGameStart.Add(function() if isClient() then ModData.request(MOD) end end)
      Events.OnReceiveGlobalModData.Add(function(key, received)
          if key == MOD and type(received) == "table" then ModData.add(MOD, received) end
      end)

      -- Trade action ------------------------------------------------------------
      IS${cls}Trade = ISBaseTimedAction:derive("IS${cls}Trade")

