          return self.character:shouldBeTurning()
      end

      function IS${cls}Trade:perform()
          state(self.character).lastTrade = getGameTime():getWorldAgeHours()
          local power = Config.get("Power")
          ${calls(["self"], "self.character", "self.character")}
          ISBaseTimedAction.perform(self)
      end

      --- Build 42: the money changes hands in complete() (server side in MP).
      function IS${cls}Trade:complete()
          local inv = self.character:getInventory()
          if inv:getCountTypeRecurse("Base.Money") < self.price then
              self.npc:Say(${say("TooPoor", "Come back when you can pay.")})
              return false
          end
          for _ = 1, self.price do inv:RemoveOneOf("Money") end
          for _, fullType in ipairs(GOODS) do inv:AddItem(fullType) end
          return true
      end

      function IS${cls}Trade:getDuration() return self.character:isTimedActionInstant() and 1 or ${Math.round(80 + n.cooldown * 10)} end

      function IS${cls}Trade:new(character, npc, cost)
          local o = ISBaseTimedAction.new(self, character)
          o.npc, o.price = npc, cost
