          player:getXp():AddXP(Perks.${perk}, Config.get("RewardXP"))
          player:getInventory():AddItem(REWARD)
          local power, zombies = Config.get("Power"), getCell():getZombieList()
          ${calls(["self"], "player", "player")}
          for i = zombies:size() - 1, 0, -1 do
              local zombie = zombies:get(i)
              if zombie:DistTo(player) <= Config.get("Radius") * 2 then
                  ${calls(["foe"], "zombie", "player")}
              end
          end
          player:setHaloNote(${T("Reward", "Quest complete")}, 120, 255, 140, 500)
      end

