      local ROWS = {
          ${rows.map(([label, expr]) => `{ getTextOrNull("IGUI_${cls}_${label.replace(/ /g, "")}") or "${label}", function(player) return ${expr} end },`)}
      }

      --- Scanning is throttled to twice a second; prerender runs every frame.
      function ${cls}HUD:prerender()
          ISPanel.prerender(self)
          if getTimestampMs() < self.nextScan then return end
          self.nextScan = getTimestampMs() + 500
          local count, zombies = 0, getCell():getZombieList()
          for i = 0, zombies:size() - 1 do
