          self:drawText(${say("Title", name)}, 10, 6, ${r}, ${g}, ${b}, 1, FONT)
          self:drawTextRight(tostring(self.zombies), self.width - 10, 6, c[1], c[2], c[3], 1, FONT)
          self:drawRect(10, LINE + 8, self.width - 20, 5, 0.6, 0.15, 0.15, 0.15)
          self:drawRect(10, LINE + 8, (self.width - 20) * math.min(1, self.zombies / (self.threshold * 3)), 5, 0.95, c[1], c[2], c[3])
          for i, row in ipairs(ROWS) do
              local y = LINE + 6 + i * LINE
              self:drawText(row[1], 10, y, 0.65, 0.65, 0.65, 1, FONT)
              self:drawTextRight(row[2](player), self.width - 10, y, 1, 1, 1, 1, FONT)
          end
      end

      --- opts = { scanRadius, threshold, threatOf(count) -> 0..3 }; all tuning comes from Config.
      function ${cls}HUD:new(x, y, player, opts)
          local o = ISPanel.new(self, x, y, 220, LINE * ${rows.length + 1} + 26)
          o.player, o.scanRadius, o.threshold, o.threatOf = player, opts.scanRadius, opts.threshold, opts.threatOf
          o.zombies, o.nextScan, o.moveWithMouse = 0, 0, true
          o.backgroundColor = { r = 0.04, g = 0.04, b = 0.05, a = 0.72 }
          o.borderColor = { r = ${r}, g = ${g}, b = ${b}, a = 0.8 }
          return o
      end`);
    const client = file(`${L}/client/${cls}Client.lua`, code`
      ${head("client", [`require "ISUI/${cls}HUD"`])}
      local huds = {}

      ${TXT}

      ${keyBind("toggle", "Toggle HUD", "KEY_H")}

      Events.OnCreatePlayer.Add(function(playerNum, player)
          if huds[playerNum] then huds[playerNum]:removeFromUIManager() end
          local x = getPlayerScreenLeft(playerNum) + getPlayerScreenWidth(playerNum) - 240
          local hud = ${cls}HUD:new(x, getPlayerScreenTop(playerNum) + 120, player, {
              scanRadius = Config.get("ScanRadius"),
              threshold = Config.get("DangerThreshold"),
              threatOf = function(count) return Config.threat(count, Config.get("DangerThreshold")) end,
          })
          hud:initialise()
          hud:addToUIManager()
          hud:setVisible(Config.get("Enabled"))
          huds[playerNum] = hud
      end)

      Events.OnKeyPressed.Add(function(key)
          if key == toggleKey() and huds[0] then huds[0]:setVisible(not huds[0]:isVisible()) end
      end)

      Events.OnPlayerDeath.Add(function(player)
          local hud = huds[player:getPlayerNum()]
          if hud then hud:removeFromUIManager() end
          huds[player:getPlayerNum()] = nil
      end)`);
    core = [client, hud];
  } else if (k === "audio") {
    /* ═════════ audio: adaptive music layers ═════════ */
    const client = file(`${L}/client/${cls}Client.lua`, code`
      ${head("adaptive soundtrack")}
      local LAYERS = { Calm = "${cls}_Calm", Tension = "${cls}_Tension", Combat = "${cls}_Combat" }
      local current, fading = { gain = 0 }, {}

      --- Picks the layer once per in-game minute; the crossfade itself happens in OnTick.
      Events.EveryOneMinute.Add(function()
          local player = getSpecificPlayer(0)
          if not player or player:isDead() or not Config.get("Enabled") then return end
          local count, zombies = 0, getCell():getZombieList()
          for i = 0, zombies:size() - 1 do
              if not zombies:get(i):isDead() and zombies:get(i):DistTo(player) <= Config.get("ThreatRadius") then count = count + 1 end
          end
          local hour = getGameTime():getHour()
          local layer = Config.layerFor(count, hour >= 21 or hour < 5, Config.get("CombatThreshold"))
          if layer == current.layer then return end
          if current.audio then table.insert(fading, { audio = current.audio, gain = current.gain }) end
          current = { layer = layer, gain = 0, audio = getSoundManager():PlaySound(LAYERS[layer], true, 0.0) }
          if layer == "Combat" then getSoundManager():playUISound("${cls}_Stinger") end
      end)

      Events.OnTick.Add(function()
          local step = Config.get("FadeSpeed") * getGameTime():getRealworldSecondsSinceLastUpdate()
          if current.audio then
              current.gain = Config.approach(current.gain, Config.get("Volume") * getCore():getOptionMusicVolume() / 10, step)
              current.audio:setVolume(current.gain)
          end
          for i = #fading, 1, -1 do
              local f = fading[i]
              f.gain = Config.approach(f.gain, 0, step)
              f.audio:setVolume(f.gain)
              if f.gain <= 0 then
                  f.audio:stop()
                  table.remove(fading, i)
              end
          end
      end)

      Events.OnPlayerDeath.Add(function()
          if current.audio then current.audio:stop() end
          current = { gain = 0 }
      end)`);
    core = [client, sounds([["Calm", true], ["Tension", true], ["Combat", true], ["Stinger", false]])];
  } else {
    /* ═════════ shaders: climate-driven colour grade ═════════ */
    const [r, g, b] = fxs[0].tint;
    const client = file(`${L}/client/${cls}Client.lua`, code`
      ${head("colour grade")}
      local TINT = { ${r}, ${g}, ${b} }
      local climate, floats, light

      ${TXT}

      local options = PZAPI and PZAPI.ModOptions and PZAPI.ModOptions:create(MOD, "${name}")
      if options then options:addTickBox("grade", ${T("Grade", "Enable colour grade")}, true) end

      --- setEnableModded hands these climate values to us without touching the save.
      local function bind()
          climate = getClimateManager()
          floats = {
              desaturation = climate:getClimateFloat(ClimateManager.FLOAT_DESATURATION),
              fog = climate:getClimateFloat(ClimateManager.FLOAT_FOG_INTENSITY),
              light = climate:getClimateFloat(ClimateManager.FLOAT_GLOBAL_LIGHT_INTENSITY),
          }
          light = climate:getClimateColor(ClimateManager.COLOR_GLOBAL_LIGHT)
          for _, f in pairs(floats) do f:setEnableModded(true) end
          light:setEnableModded(true)
      end

      local function apply()
          if not climate then return end
          local option = options and options:getOption("grade")
          local night = Config.nightFactor(getGameTime():getTimeOfDay())
          local on = Config.get("Enabled") and (not option or option:getValue())
          local blend = on and Config.clamp(Config.get("Intensity") * (Config.get("NightOnly") and night or 1), 0, 1) or 0

          floats.desaturation:setModdedValue(Config.clamp(Config.get("Desaturation") + climate:getPrecipitationIntensity() * 0.2, 0, 1))
          floats.fog:setModdedValue(Config.clamp(climate:getFogIntensity() + Config.get("FogBoost"), 0, 1))
          floats.light:setModdedValue(Config.lerp(0.85, 0.6, night))
          floats.desaturation:setModdedInterpolate(blend)
          floats.fog:setModdedInterpolate(blend)
          floats.light:setModdedInterpolate(blend * 0.5)

          local a = Config.lerp(0.25, 0.6, night)
          light:setModdedValue(ClimateColorInfo.new(TINT[1], TINT[2], TINT[3], a, TINT[1], TINT[2], TINT[3], a))
          light:setModdedInterpolate(blend * 0.6)
      end

      Events.OnGameStart.Add(function()
          bind()
          apply()
      end)
      Events.EveryOneMinute.Add(apply)`);
    core = [client];
  }

  /* ── manifest, sandbox options, translations, test ── */
  const modInfo = file("42/mod.info", [`name=${input.modName}`, `id=${cls}`, "author=Cyrus", `description=${deriveFeatures(input).join(". ")}.`, "poster=poster.png", "icon=icon.png", `modversion=${input.version}.0`, "versionMin=42.0", ""].join("\n"));
  const configLua = file(`${L}/shared/${cls}/Config.lua`, code`
    ${head("shared config", [], "")}
    ${cfgBody}

    return Config`);
  const igui = file("common/media/lua/shared/Translate/EN/IG_UI_EN.txt", blk("IG_UI_EN =", [...ui].map(([key, text]) => `IGUI_${cls}_${key} = "${text}",`)));
  const files = lite ? [...core, file("42/mod.info", modInfo.content)] : [...core, ...rest, configLua, modInfo, ...(ui.size > 1 ? [igui] : [])];

  const config = file("42/media/sandbox-options.txt", code`
    VERSION = 1,

    ${opts.map((o) => blk(`option ${cls}.${o[0]}`, [
      `type = ${o[1]},`,
      ...(o[1] === "enum" ? [`numValues = ${o[7]!.length},`] : o[1] === "boolean" ? [] : [`min = ${val(o, o[3])},`, `max = ${val(o, o[4])},`]),
      `default = ${val(o)},`, `page = ${cls},`, `translation = ${cls}_${o[0]},`,
      o[1] === "enum" && `valueTranslation = ${cls}_${o[0]},`,
    ])).join("\n")}`);
  const l10n = file("common/media/lua/shared/Translate/EN/Sandbox_EN.txt", blk("Sandbox_EN =", [
    `Sandbox_${cls} = "${name}",`,
    ...opts.flatMap((o) => [`Sandbox_${cls}_${o[0]} = "${o[5]}",`, `Sandbox_${cls}_${o[0]}_tooltip = "${o[6]}",`, ...(o[7] ?? []).map((v, i) => `Sandbox_${cls}_${o[0]}_option${i + 1} = "${v}",`)]),
  ]));

  const nth = `${interval}${["th", "st", "nd", "rd"][interval % 10 < 4 && Math.floor(interval / 10) !== 1 ? interval % 10 : 0]}`;
  const TESTS: Record<string, [string, string[]]> = {
    item: ["scales with condition and falls off with distance", ["assert.are.equal(10, Config.scaled(10, 10, 10))", "assert.are.equal(5, Config.scaled(10, 0, 10))", "assert.are.equal(1, Config.falloff(0, 6))", "assert.are.equal(0, Config.falloff(6, 6))"]],
    creatures: ["rolls variants deterministically", ["assert.is_true(Config.isVariant(5, 0.01))", "assert.is_false(Config.isVariant(999, 0.5))", 'assert.are.equal("sprint3", Config.walkType(3, 7))', 'assert.are.equal("slow2", Config.walkType(1, 4))']],
    characters: ["prices and gates trades", ["assert.is_true(Config.canTrade(nil, 0, 24))", "assert.is_false(Config.canTrade(10, 20, 24))", "assert.are.equal(8, Config.price(10, 250))", "assert.are.equal(1, Config.price(2, 1000))"]],
    vehicles: ["only boosts a healthy engine", ["assert.are.equal(6000, Config.boostForce(4000, 1.5, 100))", "assert.are.equal(4000, Config.boostForce(4000, 1.5, 0))"]],
    world: ["knows where the zone is", ["assert.is_true(Config.inZone(Config.Zone.x + 1, Config.Zone.y + 1))", "assert.is_false(Config.inZone(0, 0))"]],
    mechanics: [`fires on every ${nth} night and grows`, [`assert.is_false(Config.isEventNight(0, ${interval}))`, `assert.is_true(Config.isEventNight(${interval * 2}, ${interval}))`, `assert.are.equal(20, Config.hordeSize(20, ${interval}, ${interval}, 400))`, `assert.are.equal(25, Config.hordeSize(20, ${interval * 2}, ${interval}, 400))`, `assert.are.equal(22, Config.hordeSize(20, ${interval * 9}, ${interval}, 22))`]],
    quests: ["advances only when the goal is met", ["assert.are.equal(1, Config.advance(1, 0))", "assert.are.equal(2, Config.advance(1, 1))", "assert.are.equal(Config.Defaults.KillGoal, Config.goal(Config.Stages[2]))"]],
    interface: ["maps zombie counts to threat levels", ["assert.are.equal(0, Config.threat(0, 4))", "assert.are.equal(1, Config.threat(3, 4))", "assert.are.equal(3, Config.threat(40, 4))"]],
    audio: ["picks layers and fades smoothly", ['assert.are.equal("Calm", Config.layerFor(0, false, 5))', 'assert.are.equal("Tension", Config.layerFor(0, true, 5))', 'assert.are.equal("Combat", Config.layerFor(5, false, 5))', "assert.are.equal(0.25, Config.approach(0, 1, 0.25))"]],
    visual: ["eases in at night", ["assert.are.equal(1, Config.nightFactor(0))", "assert.are.equal(0, Config.nightFactor(12))", "assert.are.equal(5, Config.lerp(0, 10, 0.5))"]],
  };
  const probe = opts.find((o) => o[1] !== "boolean")!;
  const [title, asserts] = TESTS[slot];
  const test = file(`tests/${snake}_spec.lua`, code`
    -- busted spec for ${input.modName} · run from the mod root: busted tests
    package.path = "42/media/lua/shared/?.lua;" .. package.path
    local Config = require("${cls}/Config")

    describe("${cls} Config", function()
        after_each(function() _G.SandboxVars = nil end)

        it("falls back to the shipped defaults", function()
            assert.are.equal(${val(probe)}, Config.get("${probe[0]}"))
        end)

        it("prefers SandboxVars.${cls}", function()
            _G.SandboxVars = { ${cls} = { ${probe[0]} = ${val(probe, probe[4])} } }
            assert.are.equal(${val(probe, probe[4])}, Config.get("${probe[0]}"))
        end)

        it("gates on real-time cooldowns", function()
            assert.is_true(Config.ready(nil, 0, 5))
            assert.is_false(Config.ready(1000, 5000, 5))
        end)

        it("${title}", function()
            ${asserts}
        end)
    end)`);

  return { files, config, l10n, test };
}

