import type { CategoryKey, ModFile } from "@/lib/types";
import { ARCH, code, deriveFeatures, effectsFor, file, hashStr, identity, MODEL_NAME, numbers, type Built, type EffectKey, type TemplateInput } from "../kit";

/* ═════════════════════════ Project Zomboid · Lua · Build 42 ═════════════════════════ */

/** foe(target, source, power) hits a zombie or player · self(who, power) acts on the user · world(square, source, power) touches the map, so it runs server-side. */
type Kind = "foe" | "self" | "world";
const FX: Record<EffectKey, { kind: Kind; outfit: string; drop: string; part: string; hud: [string, string]; lua: string }> = {
  frost: { kind: "foe", outfit: "Hunter", drop: "Base.Matches", part: "Base.Aluminum", hud: ["Body temp", 'string.format("%.1f C", player:getBodyDamage():getTemperature())'], lua: `if instanceof(target, "IsoZombie") then
    target:setWalkType("slow3")
else
    local body = target:getBodyDamage()
    body:setTemperature(math.max(34.5, body:getTemperature() - power * 0.08))
    target:getStats():setFatigue(math.min(1.0, target:getStats():getFatigue() + 0.05))
end` },
  fire: { kind: "world", outfit: "Fireman", drop: "Base.Lighter", part: "Base.PropaneTank", hud: ["Outside", 'string.format("%.0f C", getClimateManager():getTemperature())'], lua: `if not square:Is(IsoFlagType.water) and not square:haveFire() then
    IsoFireManager.StartFire(getCell(), square, true, math.floor(60 + power * 4))
end` },
  storm: { kind: "world", outfit: "Police", drop: "Base.Battery", part: "Base.Battery", hud: ["Rain", 'string.format("%d%%", getClimateManager():getPrecipitationIntensity() * 100)'], lua: `getClimateManager():getThunderStorm():triggerThunderEvent(square:getX(), square:getY(), true, true, true)
getWorldSoundManager():addSound(source, square:getX(), square:getY(), square:getZ(), math.floor(power * 4), 100)` },
  blink: { kind: "self", outfit: "Survivalist", drop: "Base.ElectronicsScrap", part: "Base.ElectronicsScrap", hud: ["Endurance", 'string.format("%d%%", player:getStats():getEndurance() * 100)'], lua: `local dir, reach = who:getForwardDirection(), math.min(8, 2 + power * 0.4)
local x, y = who:getX() + dir:getX() * reach, who:getY() + dir:getY() * reach
local square = getCell():getGridSquare(math.floor(x), math.floor(y), math.floor(who:getZ()))
if square and square:isFree(false) then
    who:setX(x)
    who:setY(y)
    who:setLx(x)
    who:setLy(y)
end` },
  heal: { kind: "self", outfit: "Doctor", drop: "Base.Bandage", part: "Base.Bandage", hud: ["Health", 'string.format("%d%%", player:getBodyDamage():getOverallBodyHealth())'], lua: `if instanceof(who, "IsoPlayer") then
    who:getBodyDamage():AddGeneralHealth(power * 0.5)
else
    who:setHealth(who:getHealth() + power * 0.01)
end` },
  poison: { kind: "foe", outfit: "HazardSuit", drop: "Base.Hat_GasMask", part: "Base.Bleach", hud: ["Poison", 'string.format("%d", player:getBodyDamage():getPoisonLevel())'], lua: `if instanceof(target, "IsoPlayer") then
    local body = target:getBodyDamage()
    body:setPoisonLevel(math.min(100, body:getPoisonLevel() + power * 2))
else
    target:setHealth(target:getHealth() - power * 0.02)
    if target:getHealth() <= 0 then target:Kill(source) end
end` },
  summon: { kind: "world", outfit: "Inmate", drop: "Base.Garbagebag", part: "Base.RippedSheets", hud: ["Kills", "tostring(player:getZombieKills())"], lua: `local pack = addZombiesInOutfit(square:getX(), square:getY(), square:getZ(), math.max(1, math.floor(power / 4)), nil, 50)
for i = 0, pack:size() - 1 do
    pack:get(i):pathToSound(math.floor(source:getX()), math.floor(source:getY()), math.floor(source:getZ()))
end` },
  flight: { kind: "self", outfit: "Biker", drop: "Base.Rope", part: "Base.Rope", hud: ["Gait", 'player:isSprinting() and "sprint" or player:isRunning() and "run" or "walk"'], lua: `if instanceof(who, "IsoPlayer") then
    who:getStats():setEndurance(math.min(1.0, who:getStats():getEndurance() + 0.2))
    who:setRunSpeedModifier(1.0 + power / 25)
else
    who:setWalkType("sprint" .. tostring(ZombRand(3) + 1))
end` },
  void: { kind: "foe", outfit: "Priest", drop: "Base.Candle", part: "Base.Candle", hud: ["Panic", 'string.format("%d%%", player:getStats():getPanic())'], lua: `if instanceof(target, "IsoPlayer") then
    target:getStats():setPanic(math.min(100, target:getStats():getPanic() + power * 3))
else
    target:setTarget(nil)
end` },
  lunar: { kind: "foe", outfit: "Nurse", drop: "Base.Torch", part: "Base.Candle", hud: ["Time", 'string.format("%02d:%02d", getGameTime():getHour(), getGameTime():getMinutes())'], lua: `local hour = getGameTime():getHour()
if hour < 21 and hour >= 5 then return end
if instanceof(target, "IsoPlayer") then
    target:getStats():setFatigue(math.min(1.0, target:getStats():getFatigue() + 0.04))
else
    target:setHealth(target:getHealth() - power * 0.03)
    if target:getHealth() <= 0 then target:Kill(source) end
end` },
  auto: { kind: "self", outfit: "ConstructionWorker", drop: "Base.Screwdriver", part: "Base.Wire", hud: ["Queue", "tostring(#ISTimedActionQueue.getTimedActionQueue(player).queue)"], lua: `if not instanceof(who, "IsoPlayer") or not who:isLocalPlayer() or ISTimedActionQueue.isPlayerDoingAction(who) then return end
local bag = who:getClothingItem_Back()
if not bag or not instanceof(bag, "InventoryContainer") then return end
local inv, dest = who:getInventory(), bag:getItemContainer()
for i = inv:getItems():size() - 1, 0, -1 do
    local item = inv:getItems():get(i)
    if item:getCategory() == "Food" and not item:isFavorite() and not who:isEquipped(item) and dest:hasRoomFor(who, item) then
        ISTimedActionQueue.add(ISInventoryTransferAction:new(who, item, inv, dest))
    end
end` },
  neon: { kind: "self", outfit: "Punk", drop: "Base.LightBulb", part: "Base.LightBulb", hud: ["Moodles", "tostring(player:getMoodles():getNumMoodles())"], lua: `if instanceof(who, "IsoPlayer") and who:isLocalPlayer() then
    who:setHaloNote(getTextOrNull("IGUI_$CLS_Proc") or "$NAME", $RGB, 250)
end` },
};

/** Item and NPC contexts summon decoys instead: useless "echoes" whose noise pulls the horde away. */
const ECHO = `local echoes = addZombiesInOutfit(square:getX(), square:getY(), square:getZ(), 2, "$OUTFIT", 50)
for i = 0, echoes:size() - 1 do
    echoes:get(i):setUseless(true)
    getWorldSoundManager():addSound(echoes:get(i), square:getX(), square:getY(), square:getZ(), math.floor(power * 3), 60)
end`;

const PLACES = [
  { name: "Muldraugh", x: 10630, y: 9560 },
  { name: "West Point", x: 11860, y: 6890 },
  { name: "Riverside", x: 6420, y: 5300 },
  { name: "Rosewood", x: 8080, y: 11650 },
  { name: "March Ridge", x: 10020, y: 12680 },
];
const ORDINAL: Record<string, number> = { other: 2, second: 2, third: 3, fourth: 4, fifth: 5, sixth: 6, seventh: 7, eighth: 8, ninth: 9, tenth: 10 };

type Opt = [key: string, type: "boolean" | "integer" | "double" | "enum", def: number | boolean, min: number, max: number, label: string, tip: string, values?: string[]];
const val = (o: Opt, v: number | boolean = o[2]) => (o[1] === "double" && Number.isInteger(v) ? Number(v).toFixed(1) : String(v));
const GAP = " "; // a blank line inside `code` arrays
/** A PZ script block; nested blocks are just more strings. */
const blk = (head: string, body: (string | false)[]) => code`
  ${head}
  {
      ${body}
  }`;
const kv = (o: Record<string, string | number | boolean>) => Object.entries(o).map(([k, v]) => `${k} = ${v},`);

export function zomboidLua(input: TemplateInput): Built {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const fxs = effectsFor(input);
  const k = input.category.key;
  const arch = ARCH[k];
  const lite = input.model === "katara";
  const name = input.modName.replace(/["\\]/g, "");
  const prompt = input.prompt.toLowerCase();
  const tint = fxs[0].tint.map((c) => Math.round(c * 255)).join(", ");
  const lead = FX[fxs[0].key];
  const has = (kind: Kind) => fxs.some((e) => FX[e.key].kind === kind);
  const [L, S] = ["42/media/lua", "42/media/scripts"];
  const ord = prompt.match(/every\s+(\d+|[a-z]+?)(?:st|nd|rd|th)?\s+(?:night|day)/)?.[1];
  const interval = (ord && (Number(ord) || ORDINAL[ord])) || n.interval;
  const horde = /horde|siren|alarm|wave|swarm|migrat|night/.test(prompt);
  const place = PLACES[hashStr(cls) % PLACES.length];
  const ui = new Map<string, string>([["Title", name]]);
  if (fxs.some((e) => e.key === "neon")) ui.set("Proc", name);
  /** UI strings: registered for IG_UI_EN.txt, read through txt() with an inline fallback. */
  const T = (key: string, text: string) => (ui.set(key, text), `txt("${key}", "${text}")`);
  const say = (key: string, text: string) => (ui.set(key, text), `getTextOrNull("IGUI_${cls}_${key}") or "${text}"`);

  /* ── sandbox options: one list drives sandbox-options.txt, Sandbox_EN and Config.Defaults ── */
  const ON: Opt = ["Enabled", "boolean", true, 0, 0, "Enabled", "Turns the mod on or off for this save."];
  const POWER: Opt = ["Power", "double", n.power, 0, 50, "Effect power", "Strength of every effect this mod applies."];
  const COOL = (label: string, def = n.cooldown): Opt => ["Cooldown", "double", def, 0, 120, label, "Real-time seconds before it can trigger again."];
  const RADIUS = (label: string): Opt => ["Radius", "integer", n.radius, 1, 30, label, "Measured in tiles."];
  const LOOT: Opt = ["LootWeight", "double", 1, 0, 10, "Loot weight", "Multiplier on how often it appears in containers."];
  const int = (key: string, def: number, min: number, max: number, label: string, tip: string): Opt => [key, "integer", def, min, max, label, tip];
  const OPTS: Record<CategoryKey, Opt[]> = {
    weapons: [ON, ["Power", "double", n.power, 0, 50, "Bonus power", "Extra damage per hit and the strength of on-hit effects."], ["Chance", "double", n.chance, 0, 1, "Proc chance", "Chance that a hit triggers the special effect."], COOL("Proc cooldown (s)"), LOOT],
