// Generates every Zomboid category x model and runs a structural Lua / PZ-script check on the output.
const CATS = ["weapons", "items", "magic", "creatures", "characters", "vehicles", "worlds", "mechanics", "quests", "interface", "audio", "shaders"];
const PROMPTS = {
  weapons: ["a frost machete", "an electric storm bat"], items: ["a poison sprayer tool", "an auto-sorting backpack gadget"],
  magic: ["a blink rune", "a void shadow tome"], creatures: ["sprinting shadow zombies", "frozen walkers that summon"],
  characters: ["a mechanic companion", "a hunter who sells ammo"], vehicles: ["an armored fire truck", "a neon hover van"],
  worlds: ["a toxic swamp near riverside", "a lightning-struck forest"], mechanics: ["a horde wave every 3 nights", "an auto farming overhaul"],
  quests: ["a lunar story mission", "a fire rescue questline"], interface: ["a minimap tracker", "a frost HUD"],
  audio: ["a synthwave soundtrack", "storm ambience"], shaders: ["a neon color grade", "fog and frost lighting"],
};
const MODELS = ["katara", "sokka", "yako"];

async function gen(model, category, prompt) {
  const res = await fetch("http://localhost:3000/api/generate", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ prompt, model, context: { gameId: "zomboid", category } }) });
  const files = new Map();
  for (const line of (await res.text()).split("\n")) {
    if (!line.trim()) continue;
    const ev = JSON.parse(line);
    if (ev.type === "file") files.set(ev.path, "");
    if (ev.type === "chunk") files.set(ev.path, files.get(ev.path) + ev.text);
    if (ev.type === "error") throw new Error(ev.message);
  }
  return files;
}

function tokens(src) {
  const out = [];
  let i = 0, line = 1;
  while (i < src.length) {
    const c = src[i];
    if (c === "\n") { line++; i++; continue; }
    if (/\s/.test(c)) { i++; continue; }
    if (src.startsWith("--[[", i)) { const j = src.indexOf("]]", i); line += src.slice(i, j).split("\n").length - 1; i = j + 2; continue; }
    if (src.startsWith("--", i)) { while (i < src.length && src[i] !== "\n") i++; continue; }
    if (c === '"' || c === "'") { let j = i + 1; while (j < src.length && src[j] !== c) { if (src[j] === "\\") j++; if (src[j] === "\n") throw new Error(`unterminated string at line ${line}`); j++; } out.push({ t: "str", line }); i = j + 1; continue; }
    const w = src.slice(i).match(/^[A-Za-z_][A-Za-z0-9_]*/);
    if (w) { out.push({ t: w[0], line }); i += w[0].length; continue; }
    const num = src.slice(i).match(/^\d+(\.\d+)?/);
    if (num) { out.push({ t: "num", line }); i += num[0].length; continue; }
    const op = src.slice(i).match(/^(\.\.\.|\.\.|==|~=|<=|>=|[-+*/%^#<>=(){}\[\];:,.])/);
    if (!op) throw new Error(`bad char ${JSON.stringify(c)} at line ${line}`);
    out.push({ t: op[0], line }); i += op[0].length;
  }
  return out;
}

function checkLua(src) {
  const errs = [];
  let toks;
  try { toks = tokens(src); } catch (e) { return [e.message]; }
  const stack = [];
  const pairs = { "(": ")", "{": "}", "[": "]" };
  for (let k = 0; k < toks.length; k++) {
    const { t, line } = toks[k];
    if (t === "function" || t === "if" || t === "do" || t === "repeat") stack.push({ t, line });
    else if (t === "while" || t === "for") { /* their `do` opens the block */ }
    else if (t === "end") { const top = stack.pop(); if (!top || top.t === "repeat" || pairs[top.t]) errs.push(`unexpected end at ${line} (open ${top?.t}@${top?.line})`); }
    else if (t === "until") { const top = stack.pop(); if (!top || top.t !== "repeat") errs.push(`unexpected until at ${line}`); }
    else if (pairs[t]) stack.push({ t, line });
    else if (t === ")" || t === "}" || t === "]") { const top = stack.pop(); if (!top || pairs[top.t] !== t) errs.push(`mismatched ${t} at ${line} (open ${top?.t}@${top?.line})`); }
    // dangling binary operator / assignment right before a keyword that starts a new statement
    if (["=", "..", "and", "or", ","].includes(t)) {
      const next = toks[k + 1]?.t;
      if (!next || ["end", "local", "return", "if", "for", "else", "elseif", "then", "do", ")", "}"].includes(next) && !(t === "," && (next === "}" || next === ")"))) {
        if (!(t === "," && next === "}")) errs.push(`dangling '${t}' at ${line} before '${next}'`);
      }
    }
  }
  for (const s of stack) errs.push(`unclosed ${s.t} from line ${s.line}`);
  return errs;
}

function checkScript(path, src) {
  const errs = [];
  let depth = 0;
  src.split("\n").forEach((l, i) => {
    const s = l.trim();
    for (const ch of s) { if (ch === "{") depth++; if (ch === "}") depth--; }
    if (depth < 0) errs.push(`brace underflow at ${i + 1}`);
    if (/=\s*,\s*$/.test(s) || /=\s*$/.test(s) && !path.endsWith("mod.info")) errs.push(`empty value at ${i + 1}: ${s}`);
    if (/undefined|NaN|\[object/.test(s)) errs.push(`bad value at ${i + 1}: ${s}`);
  });
  if (depth !== 0) errs.push(`unbalanced braces (${depth})`);
  return errs;
}

let failures = 0, checked = 0;
const jobs = [];
for (const cat of CATS) for (const [pi, prompt] of PROMPTS[cat].entries()) for (const model of MODELS) jobs.push({ cat, prompt, model: MODELS[(MODELS.indexOf(model) + pi) % 3] });
const seen = new Set();
const unique = jobs.filter((j) => { const key = `${j.cat}|${j.prompt}|${j.model}`; if (seen.has(key)) return false; seen.add(key); return true; });
for (let b = 0; b < unique.length; b += 8) {
  await Promise.all(unique.slice(b, b + 8).map(async ({ cat, prompt, model }) => {
    const files = await gen(model, cat, prompt);
    for (const [path, src] of files) {
      if (path.endsWith(".md")) continue;
      checked++;
      const errs = path.endsWith(".lua") ? checkLua(src) : checkScript(path, src);
      if (/undefined|NaN|\[object Object\]/.test(src)) errs.push("contains undefined/NaN/[object Object]");
      if (errs.length) { failures++; console.log(`FAIL ${cat}/${model} "${prompt}" ${path}\n  ${errs.slice(0, 6).join("\n  ")}`); }
    }
    console.log(`ok ${cat}/${model} "${prompt}": ${files.size} files`);
  }));
}
console.log(`\n${checked} files checked, ${failures} with problems`);

