import fs from "node:fs";
const s = fs.readFileSync(process.argv[2], "utf8");
const names = [...s.matchAll(/\bconst (?:\[([^\]]+)\]|([A-Za-z_]\w*))/g)].flatMap((m) => (m[1] ? m[1].split(",").map((x) => x.trim()).filter(Boolean) : [m[2]]));
